WordHunterWoW_QuestEN[93828] = { title = "Herbs of the Hollow", description = "The mountain's breath is damp here by the spring, and my herbs will not dry in this thick air. When our kin return from the wild, they hang their packs wherever the roots allow good air, spread through the den.\n\nGo now. Find the strands of dried herbs hung round our home and bring them to me. With them, I will weave wraps and wards to keep our spirits strong.", objectives = "Collect 10 Dried Hanging Herbs from around Barkskin Burrow and return them to Fennar Mossmane." }
WordHunterWoW_QuestEN[93830] = { title = "Water of Hyjal", description = "The Deadwood dwell by a pond born of Mount Hyjal's snow melt. That water is pure, strong with the mountain's breath. We use it for our draughts and to save roots from death.\n\nHere, the springs run slow. Our source must be saved, and used with care. But their pond flows with life, it could fill our den twice over. Bring me a skin filled with that water, friend. Spirits will bless your steps, and our den will drink deep of the mountain's gift.", objectives = "Fill a waterskin provided by Fennar Mossmane at the pond outside of the Deadwood Furbolg den." }
WordHunterWoW_QuestEN[93831] = { title = "Sweetpaw Jam", description = "You smell like mountain winds, strong and free! I have a task, if your paws are not full.\n\nWe love bear berries, they're round, red, and sweet as honey after frost. Look for them near the shade of trees. Too many sharp rocks and mad wings for us to get the ripest bush.\n\nBring me a bunch, and I make Sweetpaw Jam! My best treat, and I will share a taste.\n\nDeal?", objectives = "Gather 30 Bear Berries from Hyjal and return to Osi Mistpaw." }
WordHunterWoW_QuestEN[93832] = { title = "Shatter the Stonewatchers", description = "High slopes hold stone wings. Rock-beasts. Half-live, half-dead. Foul hands carve them. Do not trust their still pose. These eyes wait for one wrong step.\n\nOur young do not know the risk. One paw too near, and stone wakes with claw and fang.\n\nGo, smash these cursed forms. Break their wings, crush their shards, and let the mountain breathe free.", objectives = "Destroy 6 Eternal Sentry gargoyles in the destroyed Alliance base in upper Hyjal and return to Elder Mistpaw." }
WordHunterWoW_QuestEN[93833] = { title = "Wicked Wisdom", description = "The owls of Hyjal are more than feathers and flight. Their talons, their plumes, even the bones whisper of the wild. We use these gifts to craft talismans, charms that bind the spirits and shield our kin.\n\nBut the owls do not give freely. You must take what the mountain offers. Kill 5 owls and bring their carcasses to me.\n\nYes, we ask you to return the whole body to us, as we waste nothing provided by such graceful creatures.", objectives = "Bring 5 owl bodies to Elder Pinespeaker in Barkskin Burrow in Hyjal." }
WordHunterWoW_QuestEN[93834] = { title = "Burrow Beetles", description = "Burrow beetles! They're a bane... and now they dig in our den more than their own. We beat them back and swing clubs when we see them skulk by, but they are quick, and to hide in the dark is their shield.\n\nIf you spot them as you climb our den, squash them! We will take their crushed shells and make a meal, so it is not all bad.", objectives = "Gather 6 Burrow Beetle Bits for Dala Fairmaw." }
WordHunterWoW_QuestEN[93835] = { title = "Confront Lorthuna", description = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\n\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Elaadrin and help them stop Lorthuna.\n\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, {class}.", objectives = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with High Priestess Lorthuna.", completion = "I sent a few of our remaining mages to ensure that Valennia and her forces were able to escape as well. She should be resting at High Elder Shadowsong's residence now.\n\nAnsirem had to return to Azeroth, but he and I discussed the next steps for the High Order before he departed. We survived the day, but Zephras is dangerously vulnerable now and we must make plans for what is to come." }
WordHunterWoW_QuestEN[93836] = { title = "The Fate of Zephras", description = "Muln has told me much of the elemental lords and I am afraid that we have good reason to fear Al'Akir. Now that the wards that have hidden Zephras from his view are down, we are utterly defenseless. If he chooses to attack us, we stand no chance against him here in his own domain.\n\nHigh Elder Shadowsong needs to know of the danger we are in, and more importantly, what our intentions are for our mission to Azeroth. We will find the means to save our home. I swear it.", objectives = "Speak with Talaanis Shadowsong in Valanaar.", completion = "<Talaanis Shadowsong listens intently as you tell him of what transpired above the Shrine of Akir, and of Ayessa's plan to leave Zephras Isle.>\n\nI need to reflect on this further, but looking at the upside, we have rid ourselves of Lorthuna and deprived the cult of their leader. Our home has not been invaded yet and on the timeline of elemental gods, it could be years... decades even, before Al'Akir deigns to turn his attention to us.\n\nThere is much to fear now, but much to celebrate as well." }
WordHunterWoW_QuestEN[93848] = { title = "Work Well Done", description = "The magic that Ketharas was able to craft to counteract this threat was vital to this victory. Our druids should be able to replicate the magic and use it to dispel the wards empowering the Blackthorne Pact at scale.\n\nYou should go back to Ketharas and let him know what transpired here. Tell him that he has the thanks of the Guardians of Hyjal and the Cenarion Circle. He should know that he is always welcome amongst us should he desire a place alongside his fellow druids once again.", objectives = "Return to Ketharas and inform him of what occurred at the Summit of Eternity." }
WordHunterWoW_QuestEN[93862] = { title = "Crate Return", description = "", objectives = "" }
WordHunterWoW_QuestEN[93926] = { title = "The Western Watch", description = "Whatever reason the cult has for attacking the tower, it's not worth losing our people over.\n\nI'd like for you to head to the southwest and check in on that watchtower for us. Find the peacekeepers there and tell them to head back to the village. Holding that tower is not worth the lives it would cost and I'd rather concentrate the defenders we do have here to protect our citizens.\n\nPeacekeeper Vaaniel is in charge; let him know to head back here as quickly as possible. Hurry!", objectives = "Find Peacekeeper Vaaniel at the western watchtower.", completion = "<The body here is somewhat fresh, clearly only recently having been killed. Judging by the burns and scorch marks on this peacekeeper's skin, it's clear that they were killed by the cult's storm-wielding spellcasters.>" }
WordHunterWoW_QuestEN[93927] = { title = "A Last Request", description = "<As you inspect the body of the dead peacekeeper, a bloody note falls free of his hands. Picking it up and reading it may give you a clue as to how to proceed from here.>", objectives = "Collect the note you found near the dead peacekeeper and read it to determine your next steps.", progress = "What news from the western watch?", completion = "So they are all dead, then. Storms curse these cult bastards!\n\nWhile you managed to take out the priest and stop the cultists at the tower, I confess that I'm now doubly concerned about whatever it was you said that they were doing to the pylon. The fact that there was such a massive cache of windstones there with them tells me that they needed enormous energy for it.\n\nI have to wonder, what's the end goal here? Violating the pylon, attacking the village? To what end?" }
WordHunterWoW_QuestEN[93928] = { title = "Of Mice and Milk", description = "I need a cookie, see? \n\nNyeah!", objectives = "Get the mouse a cookie.", completion = "(PH) Thanks!" }
WordHunterWoW_QuestEN[93948] = { title = "Deliver the Signet", description = "Since you are going to Valanaar anyway, please deliver the signet ring you recovered from the tower to Talaanis Shadowsong in Valanaar. \n\nHe will want this back, and more importantly, he will want to learn the fate of his nephew. Talaanis is the High Elder of Zephras Isle and more importantly, he is a good man who is well loved by the people, despite our current hardships. It pains me to think of how he will react to this news. Please express my condolences for his loss.", objectives = "Deliver the Shadowsong Family Signet to Talaanis Shadowsong in Valanaar.", progress = "What is that you have for me? Oh... oh no.", completion = "I... am very sorry to hear that my nephew is dead. I thank you kindly for recovering this, and bringing it to me.\n\nIt's not common that such capable young shen'dorei come down from the highlands. If you need work, please speak with Valennia Stormfist, the captain of the peacekeepers here in Valanaar. These days we need all the help we can get." }
WordHunterWoW_QuestEN[93949] = { title = "Bugged", description = "We've been bugged.\n\nIt's skyhopper season in the lowlands, which means the pests are everywhere. One of the High Order mages reported that one of the insects that they killed had an enchantment of some kind placed upon it. When we inspected it closely it seems to be some sort of listening spell.\n\nWe suspect that the cult is using these enchanted insects as spies. Go and exterminate them for us. You won't be able to tell which are enchanted by looking at them, so you'll just have to kill them all.", objectives = "Kill Skyhoppers in Valanaar until you've eliminated 8 Enchanted Skyhoppers.", completion = "I'm sure there are more of these critters around Valanaar, but every enchanted skyhopper we stomp out makes the city just a tiny bit safer." }
WordHunterWoW_QuestEN[93951] = { title = "A Little Beauty", description = "The hippogryphs that have taken up residence southwest of the village can be a nuisance, but they also present a rather unique opportunity to obtain their feathers. Many skyborne love to adorn their hair with vibrant plumes and the down feathers of a hippogryph are exceptionally vibrant and, more importantly, silky soft.\n\nIf you are heading that way, try and gather as many of the fallen feathers as you can from around their nesting grounds. Do be careful, as wild hippogryph are not tolerant of guests.", objectives = "Collect 8 Hippogryph Down feathers in the Shen'dar Highlands.", progress = "What beautiful things did you bring me?", completion = "It might seem a bit of a vain triviality, gathering feathers for our hair. However, even in times like these, one needs to embrace the small joys as much as possible. \n\nIf one thing I create brings someone joy, then I will consider that to be a good day. Thank you for bringing me these and helping me bring some joy to Zephras." }
WordHunterWoW_QuestEN[93952] = { title = "Balance Through Strength", description = "Barkskin stand on weak roots. Deadwood claw at our land, each day their rot digs deep, sinks more. We cannot hold alone. \n\nDeadwood Den guards are the brunt of their strength. If you seek our trust, strike down those who foul the wood. When their Guardians fall, the rest of their tribe will weaken. We even our odds.\n\nBring them down, for balance, and help keep Hyjal whole.", objectives = "Defeat 9 Deadwood Den Guardians and return to Brerufa." }
WordHunterWoW_QuestEN[93958] = { title = "The Inner Sanctum", description = "Valennia's forces just breached the inner sanctum. The fighting was thick in there at first, but it's grown... unsettlingly quiet. Go in there and do your best to link up with Valennia and her forces... if any of them are left.\n\nI'll stay here and watch your back.", objectives = "Speak with Valennia Stormfist inside the inner sanctum at the Shrine of Akir.", completion = "<Valennia looks gravely wounded.>" }
WordHunterWoW_QuestEN[93963] = { title = "Exploring the Alliance", description = "Stormwind, Ironforge, and Darnassus all have unique peoples and cultures. As a guest of the Alliance here on Azeroth, you should take some time to visit each of our capital cities in turn. \n\nSpeak with Randal Emerson in the southern antechamber for directions to get you started.", objectives = "Speak with Randal Emerson in Stormwind Keep to receive further instructions. Use the instructions received to locate and speak with King Magni Bronzebeard, High Tinker Mekkatorque, and Tyrande Whisperwind.", completion = "Ah, you are back.\n\nI hope your adventures have given you a sense of the scale and wonder of our world. I know it must seem overwhelming to you, but if you are to help your people, you must be prepared for whatever may come your way while you are on Azeroth.\n\nWhile you wait for your order to establish itself in Dalaran, I suggest you turn your attention to the lands around Stormwind. Westfall in particular can always use more strong adventurers to lend them aid, if you are willing." }
WordHunterWoW_QuestEN[93971] = { title = "Farholde Scouting Report", description = "<The report is sealed with the sigil of Farholde. This information may be of interest to Krom'rosh at Rog'mar.>", objectives = "Bring the report to Krom'rosh at Rog'mar." }
WordHunterWoW_QuestEN[93976] = { title = "The Goblin Trader", description = "While Gur'dok and I continue our work, we did fashion a particular blade for a friend--perhaps friend is too strong a word--for an acquaintance down at the docks. This particular individual is well known and connected all across the Kingdoms and beyond.\n\nTake this. When you deliver it, let her know I sent you. And tell her we're even.", objectives = "Deliver the blade to Kreza Darkthorn's acquaintance at the docks east of Rog'mar." }
WordHunterWoW_QuestEN[94003] = { title = "The Skybreaker Bulwark", description = "I am all that remains of the line of Skybreakers here on Zephras Isle. The rest were murdered by the Al'Aketh.\n\nThe only thing that outweighs my sorrow is my shame. My family's ancestral shield--the Skybreaker Bulwark--is now in the hands of a cultist named Zaal Stormshield. Family lore holds no harm may befall a worthy wielder of this shield.\n\nZaal is not worthy, of that I am sure. Find this man at the Shrine of Akir and reclaim my shield from him. Do this and I will teach you the Skybreaker Defense.", objectives = "Reclaim the Skybreaker Bulwark from Zaal Stormshield at the Shrine of Akir.", progress = "<Seena nods curtly at you.>", completion = "You have done what I could not and restored my family honor. For this, I will bestow a gift that few on Zephras are worthy to receive. I will teach out the secrets of the Skybreaker Defense.\n\nAlso, you will need a shield to put what I have to teach you into practice. Please, take this one. I have little use for it now that the Skybreaker Bulwark has been returned to me.\n\nBanu'Adoraah, friend." }
WordHunterWoW_QuestEN[94004] = { title = "Craftsman's Writ: Elixir of Ogre's Strength", description = "<Penned in faded ink, the note is requesting 1 Elixir of Ogre's Strength, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Wut?", completion = "You brought da elixir!!\n\nT'anks, {race}. You come all this way to help Sos'mol. No ogre ever done that before.\n\nSos'mol will remember this. Pay you back someday. Me promise." }
WordHunterWoW_QuestEN[94006] = { title = "The Great Ursera Spirit", description = "Greetings, {name}. You have progressed in your druidic studies far enough that I think it is time for you to meet one of the great spirits that reside here on Zephras. Urs'endris is a wise and noble spirit, who has taught druids how to take on the ursera shape for generations. Unfortunately his domain has begun to wither and fall into the sky like many other areas of Zephras.\n\nTo find him, travel northeast near the waterfall in the shadow of the Shrine of Akir. He should be able to instruct you further.", objectives = "Speak with Urs'endris near the falls northeast of Valanaar.", completion = "So, you wish to embrace the way of the claw, child? Very well. Let us speak." }
WordHunterWoW_QuestEN[94007] = { title = "Taming the Beast", description = "Now that you've gained a level of comfort in the wilds of the highlands, I believe it is time for you to seek your very own animal companion.\n\nGo to the port of Valanaar to the southeast, and speak with Quel'ana Quickgale there. He will instruct you in the art of beast taming.", objectives = "Report to Quel'ana Quickgale in Valanaar.", completion = "I am most glad that you came. Come, let us begin." }
WordHunterWoW_QuestEN[94013] = { title = "Taming the Beast", description = "You've returned triumphant from taming two beasts. It's time now for your last trial. The winds of Zephras whisper of greater challenges ahead. \n\nTake this Taming Rod and journey to the Gustberry Lowlands. There, tame a Vuldren Alpha and prove your mastery. \n\nComplete this lesson and you'll be ready to learn the deeper ways of the hunter.", objectives = "Use the Taming Rod to tame a Vuldren Alpha in the Gustberry Lowlands. Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "Excellent, {name}! You are quite a fast learner. Now that you know the basics, I can teach you how to forge a lasting bond with an animal companion.\n\nGo with this knowledge and thrive. Be the {class} that Zephras Isle needs you to be." }
WordHunterWoW_QuestEN[94049] = { title = "zzOLD Training the Beast", description = "I've gotten you started down the path of animal companionship, but my there is no better expert at training beasts than my brother, Quel'dora. Speak with him now and he will teach you what you need to know.", objectives = "Speak with Quel'dora Quickbreeze in Valanaar to learn to train pets." }
WordHunterWoW_QuestEN[94050] = { title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it. For this, there is none better than my sister, Quel'dora. She will give you the ability to train your new pet. \n\nGo with the winds, young {class}.", objectives = "Speak to Quel'dora Quickgale in Valanaar.", completion = "A fledgling {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember, {name}, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date." }
WordHunterWoW_QuestEN[94212] = { title = "Craftsman's Writ: Elixir of Wisdom", description = "<Penned in faded ink, the note is requesting 1 Elixir of Wisdom, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Come, warm yourself by the fire.", completion = "I will admit, I expected the treacherous winds of the highlands to tear that letter to shreds. I had not imagined that someone would see my humble request, let alone deliver it straight to me.\n\nYour efforts are kind and admirable, {race}. I will use this to aid my meditation.\n\nFeel free to stay and share a tale or two of your travels. I enjoy the company." }
WordHunterWoW_QuestEN[94213] = { title = "Craftsman's Writ: Lesser Mana Potion", description = "<Penned in faded ink, the note is requesting 1 Lesser Mana Potion, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Good day, {race}. I appreciate the company but my attention is elsewhere. If we do not have business, please be on your way.", completion = "Ah, is this the potion I requested?\n\n<The elven woman respectfully takes the vial from you.>\n\nYour arrival is timely, and generosity deeply appreciated. I accept this, and offer you a small token of my gratitude.\n\nThank you, may we meet again." }
WordHunterWoW_QuestEN[94214] = { title = "Craftsman's Writ: Shadow Protection Potion", description = "<Penned in faded ink, the note is requesting 1 Shadow Protection Potion, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Heyo, for future reference, you shouldn't come charging at full-speed toward a goblin with a bodyguard! You never know what might happen.", completion = "Then again, when you're fulfilling a rush order like this one, I can't blame you for wanting to capitalize on your gains.\n\nHere you go, pal. Thanks for hooking a goblin up with some much-needed shadow protection potions. Have you SEEN the stuff that goes on out here?" }
WordHunterWoW_QuestEN[94215] = { title = "Craftsman's Writ: Free Action Potion", description = "<Penned in faded ink, the note is requesting 1 Free Action Potion, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<You approach a thrashing creature clearly trapped in spider silk, exactly where the writ marked on the map.>", completion = "<You waste little time offering the wiggling mass the Free Action Potion that was requested. It seems either unaware of your presence, or unable to claim the item.\n\nA handful of coins are scattered just beside the cocoon. You may decide to leave the potion there, and take the coins for yourself. Nature will surely sort itself out, in that case.>" }
WordHunterWoW_QuestEN[94216] = { title = "Craftsman's Writ: Elixir of Lesser Agility", description = "<Penned in faded ink, the note is requesting 1 Elixir of Lesser Agility, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Are you here about...\n\n<Ziz looks around his tiny hut suspiciously, and lowers his voice.>\n\nThe elixir?", completion = "<Ziz continues to talk in a hushed tone.>\n\nI'm not about to give you the whole spiel about how I got into this position, but here's some advice for you.\n\nSometimes, all you gotta do to impress your new boss is take credit for someone else's work. So you're going to hand over the elixir, and I am gonna talk about how much blood, sweat, and tears I poured into making it.\n\nIt's a new gig, okay? I need to make a good first impression!" }
WordHunterWoW_QuestEN[94217] = { title = "Craftsman's Writ: Lesser Troll's Blood Elixir", description = "<Penned in faded ink, the note is requesting 1 Lesser Troll's Blood Elixir, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yarr, you be bringin' me my elixir?", completion = "Exactly what Short John Mithril ordered!\n\nHere's ye' coin. I'd keep it clutched to your chest as ye' scuttle out of here, the arena combatants thirst for riches as much as they thirst for blood!" }
WordHunterWoW_QuestEN[94218] = { title = "Craftsman's Writ: Elixir of Defense", description = "<Penned in faded ink, the note is requesting 1 Elixir of Defense, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94219] = { title = "Craftsman's Writ: Draught of Water Breathing", description = "<Penned in faded ink, the note is requesting 1 Draught of Water Breathing, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94220] = { title = "Craftsman's Writ: Pearl-Handled Dagger", description = "<Penned in faded ink, the note is requesting 1 Pearl-Handled Dagger, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "It is unwise to sneak up on me, {race}. Speak quickly, and speak quietly.", completion = "Oh, you are delivering my dagger? Hah, I suppose my threat rang quite hollow then, hm?\n\nI must stay on high alert given my duties here, and especially with oth-- ahem, the foul Syndicate roaming about elsewhere here.\n\nWould you be so kind as to part with the blade, now? I must get back to my task." }
WordHunterWoW_QuestEN[94221] = { title = "Craftsman's Writ: Golden Rod", description = "<Penned in faded ink, the note is requesting 1 Golden Rod, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The dwarf seems to be in a deep state of meditation, though your approach interrupted his focus. Fortunately, a smile greets you.>", completion = "Ah, the Golden Rod I requested. I never expected it to arrive. I was considering going back to Ironforge to purchase one off the auction house. You saved me a trip, something these old feet greatly thank you for.\n\nI do not yet know how I can use this to commune with the Binding Stones, let alone if I even can, but I suspect this brings me one step closer.\n\nIn the worst case, well, I am happy to have a new cane." }
WordHunterWoW_QuestEN[94222] = { title = "Craftsman's Writ: Iridescent Hammer", description = "<Penned in faded ink, the note is requesting 1 Iridescent Hammer, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94223] = { title = "Craftsman's Writ: Silver Skeleton Key", description = "<Penned in faded ink, the note is requesting 1 Silver Skeleton Key, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<After following the instructions on the writ, you find yourself deep in a crypt surrounded by undead. There is a note on a nearby trunk.>\n\nWhomever first reads this will be the first to learn of my death. I am a mere caretaker of the Raven Hill Cemetery, whose presence is largely forgotten by even his employers at Darkshire. I have no heir with which to bestow my vast wealth unto. I have since stashed them away, in this box, for who or whatever manages to open it.", completion = "<With the undead hordes endlessly gathering nearby and no sign of others, you choose to make use of your Silver Skeleton Key to effortlessly open the chest.\n\nDespite the claims of impressive riches, the trunk is nearly empty. At the very least there is enough present to cover some of the cost of this ordeal.>" }
WordHunterWoW_QuestEN[94224] = { title = "Craftsman's Writ: Heavy Bronze Mace", description = "<Penned in faded ink, the note is requesting 1 Heavy Bronze Mace, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Shh. Keep your voice down. I'm not ready for a fight, yet.", completion = "Whoa. You came well prepared! Hope that mace is for me, unless you plan to do ALL of the fighting." }
WordHunterWoW_QuestEN[94225] = { title = "Craftsman's Writ: Rough Bronze Leggings", description = "<Penned in faded ink, the note is requesting 1 Rough Bronze Leggings, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "What's up?", completion = "These are the leggings I ordered, huh? \"Three to five business days,\" they said. More like three to five business MONTHS!\n\nI submitted this when I was working for the Venture Co out there, and let me just say, that partnership is well over with, so we can consider this order expired.\n\nWhy aren't you leaving yet? Ugh, fine! Here's your payment." }
WordHunterWoW_QuestEN[94226] = { title = "Craftsman's Writ: Green Iron Gauntlets", description = "<Penned in faded ink, the note is requesting 1 Green Iron Gauntlets, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94227] = { title = "Craftsman's Writ: Big Bronze Knife", description = "<Penned in faded ink, the note is requesting 1 Big Bronze Knife, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The chicken... clears its throat?>\n\nCluck, cluck.", completion = "Cluck? CLUCK CLUCK! BWOK!\n\n<The chicken glares menacingly toward Magus Tirth from afar, newly acquired blade in beak.>" }
WordHunterWoW_QuestEN[94228] = { title = "Craftsman's Writ: Green Iron Boots", description = "<Penned in faded ink, the note is requesting 1 Green Iron Boots, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Please tell me you're the one with the boots...", completion = "At last! I've been stomping around the wetlands with soggy feet for days!\n\nHopefully these aren't prone to rusting either. I trust you know what you're doing." }
WordHunterWoW_QuestEN[94229] = { title = "Craftsman's Writ: Ornate Spyglass", description = "<Penned in faded ink, the note is requesting 1 Ornate Spyglass, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Whoa! I almost didn't see you there. I might have seen you coming sooner if a damned engineer would at last deliver my order.", completion = "Oh. Oh! You're the engineer? I suppose at the very least you are the delivery boy in any case.\n\nPlease hand over the spyglass. I have little time and many things to inspect." }
WordHunterWoW_QuestEN[94230] = { title = "Craftsman's Writ: Explosive Sheep", description = "<Penned in faded ink, the note is requesting 1 Explosive Sheep, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94231] = { title = "Craftsman's Writ: Moonsight Rifle", description = "<Penned in faded ink, the note is requesting 1 Moonsight Rifle, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Hey, HEY, man, haven't you heard of a little thing called \"subtlety\"? Spell it out with me, S-U-B...LETY. You're going to blow my cover!", completion = "Ohoho, I take it back. Look at this beautiful boomstick. I bet it'll knock a satyr's head clean off.\n\nThanks pal, now step aside or you're going to get caught in the crossfire." }
WordHunterWoW_QuestEN[94232] = { title = "Craftsman's Writ: Minor Recombobulator", description = "<Penned in faded ink, the note is requesting 1 Minor Recombobulator, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", completion = "I don't know what I expected when I sent out an order for a curse dispelling device, but this Minor Recon--Racom--ugh, Minor Whatchamacallit sure ain't it!\n\nLook, I know how complicated the refund process is and I do NOT have time for that. It's way easier for us both if I just take this off your hands, and I'll be more specific with my next order.\n\nFor both of our sakes, let's hope you don't screw that one up too!" }
WordHunterWoW_QuestEN[94233] = { title = "Craftsman's Writ: Practice Lock", description = "<Penned in faded ink, the note is requesting 1 Practice Lock, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "I watched this whole place get burned to the ground and that keep toppled over. It was glorious.\n\nNever expected a group of bandits try to use this place as a base of operations.", completion = "Ahh, my practice lock has arrived.\n\nThe Syndicate here have been plotting to turn this place into a prison like it once was. I already know that at least one orc is currently being held here. Maybe more. I don't intend to be another, but I intend to be more prepared than the last time if they catch me off guard." }
WordHunterWoW_QuestEN[94234] = { title = "Craftsman's Writ: Shadow Goggles", description = "<Penned in faded ink, the note is requesting 1 Shadow Goggles, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Hey! Watch where you're walking!", completion = "My new shadow goggles!\n\n<Without another word, the goblin tossed a handful of coins your way with one hand while the other swiped the item out of your grasp. The transaction was completed and his attention lost before you had a moment to process what happened.>" }
WordHunterWoW_QuestEN[94235] = { title = "Craftsman's Writ: Gnomish Universal Remote", description = "<Penned in faded ink, the note is requesting 1 Gnomish Universal Remote, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Careful where you walk, Gizmo! This thing likes to activate when you least expect it, and we don't quite have a handle on where it can take you when we aren't actively manning the controls.", completion = "Seems we are in luck, the remote has arrived! Looks like you precalibrated it for us which, I'll admit, isn't ideal for this scenario.\n\nI should be able to reverse engineer it in no time. Then maybe, hopefully, I'll be able to take a much needed break. Feels like I've been stuck fumbling with this teleporter's controls for months on end!" }
WordHunterWoW_QuestEN[94236] = { title = "Craftsman's Writ: Big Bronze Bomb", description = "<Penned in faded ink, the note is requesting 1 Big Bronze Bomb, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "You got the stuff?", completion = "Hey, there's the bomb I ordered!\n\nWell, one of them anyway. I needed a variety pack! You know, enough so I can test each one for effectiveness AND have a few leftover for my own needs!\n\nWell, whatever. Here's a cut of your cut, I'll give you the rest when you bring ME my full order!" }
WordHunterWoW_QuestEN[94237] = { title = "Craftsman's Writ: Crafted Solid Shot", description = "<Penned in faded ink, the note is requesting 200 Crafted Solid Shot, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94238] = { title = "Craftsman's Writ: Heavy Leather Ball", description = "<Penned in faded ink, the note is requesting 1 Heavy Leather Ball, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94239] = { title = "Craftsman's Writ: Fine Leather Pants", description = "<Penned in faded ink, the note is requesting 1 Fine Leather Pants, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Move along, please, and try not to draw attention to us.", completion = "Oh! The pants? Ah, I realized shortly after writing this that I needed a full set of clothes - new overalls included.\n\nIf it will get you out of my hair, I suppose I should honor the request. After all, you did make an arduous journey to find me.\n\nTake this, now please...\n\n<She gestured in a polite but firm shooing motion.>" }
WordHunterWoW_QuestEN[94240] = { title = "Craftsman's Writ: Herbalist's Gloves", description = "<Penned in faded ink, the note is requesting 1 Herbalist's Gloves, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94241] = { title = "Craftsman's Writ: Dark Leather Tunic", description = "<Penned in faded ink, the note is requesting 1 Dark Leather Tunic, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "WHAT???", completion = "Oh your timing is impeccable!\n\nCallahan! Your new shirt arrived. Hurry up and change so I can stop hearing about how itchy you are all the time.\n\nAnd for you, {race}. Here is your payment. Before you wander off, you should take a look at my wares now that you can afford 'em!" }
WordHunterWoW_QuestEN[94242] = { title = "Craftsman's Writ: Pilferer's Gloves", description = "<Penned in faded ink, the note is requesting 1 Pilferer's Gloves, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94243] = { title = "Craftsman's Writ: Heavy Quiver", description = "<Penned in faded ink, the note is requesting 1 Heavy Quiver, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Need some work?", completion = "I--Hmm.\n\nI don't remember why I ordered this.\n\n<Ziz shrugs and tosses the quiver into a nearby pile of junk.>" }
WordHunterWoW_QuestEN[94244] = { title = "Craftsman's Writ: Dark Leather Shoulders", description = "<Penned in faded ink, the note is requesting 1 Dark Leather Shoulders, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yarr, what business do ye' have with ol' Narkk?", completion = "Thar be me shoulderpads, at last!\n\nEver had one of these squakers perch on your shoulder? Bet ye' haven't! Their claws, they hurt!\n\nNow they got a place to rest all day, and you have a heavier coinpurse!\n\n<Narkk eyes said coinpurse.>\n\nFor now!" }
WordHunterWoW_QuestEN[94245] = { title = "Craftsman's Writ: Barbaric Gloves", description = "<Penned in faded ink, the note is requesting 1 Barbaric Gloves, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94246] = { title = "Craftsman's Writ: Red Whelp Gloves", description = "<Penned in faded ink, the note is requesting 1 Red Whelp Gloves, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94247] = { title = "Craftsman's Writ: Lesser Wizard's Robe", description = "<Penned in faded ink, the note is requesting 1 Lesser Wizard's Robe, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The man stands at attention, peering over the mountainside toward Dalaran. He regards your presence with a subtle wave of a hand, beckoning you closer.>", completion = "<Alan speaks in a whisper.>\n\nDon't you think it is a little suspicious to be carrying elegant robes in broad daylight to a man garbed in dark leathers?\n\nWell, ahem, fortunately I am out here on behalf of the Kirin Tor, so there is no shady transaction about to take place. None at all.\n\nThe robe, please." }
WordHunterWoW_QuestEN[94248] = { title = "Craftsman's Writ: Blue Overalls", description = "<Penned in faded ink, the note is requesting 1 Blue Overalls, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Oh! Please keep your voice down, we don't need to draw any further attention to ourselves.\n\nDo you have something for me?", completion = "The Blue Overalls! Thank goodness, I have a proper change of clothes.\n\nTake this, and please be on your way. I do not have time to chat, I must keep an eye on the farm and can't risk more distractions." }
WordHunterWoW_QuestEN[94249] = { title = "Craftsman's Writ: Azure Silk Hood", description = "<Penned in faded ink, the note is requesting 1 Azure Silk Hood, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "AHHHH! Oh, it just a {race}.\n\nHi {race}!", completion = "It da hood me order-er-ed!\n\nMe forgot why wanted in first place, but me take anyway.\n\nHere, take shiny coin. It fell out of slime monster. Lots and lots of them!" }
WordHunterWoW_QuestEN[94250] = { title = "Craftsman's Writ: Small Silk Pack", description = "<Penned in faded ink, the note is requesting 1 Small Silk Pack, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yo! Is that pack for me?", completion = "Ha ha! Thanks, pal. I owe you.\n\n<Kzixx reaches into a Small Silk Pack already in his possession, filled to the brim with coin, and pulls out a fist full. He counts out a tiny fraction of his total wealth, and hands it to you.>\n\nThis should cover it. No take-backs!" }
