WordHunterWoW_QuestEN[94254] = { title = "Craftsman's Writ: Greater Adept's Robe", description = "<Penned in faded ink, the note is requesting 1 Greater Adept's Robe, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<Magus Tirth begins to cast Polymorph: Chicken on you.>", completion = "My new robe! Delightful!\n\nAt long last, I can don my robe AND my wizard hat." }
WordHunterWoW_QuestEN[94255] = { title = "Craftsman's Writ: Spider Silk Slippers", description = "<Penned in faded ink, the note is requesting 1 Spider Silk Slippers, along with information about delivery location and payment. At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yo!", completion = "Are these my new boots?\n\n<Kixxle looks very excited, but it fades immediately upon setting his eyes upon them.>\n\nAh. I thought I had cancelled the order for slippers once I realized how foolish it would be to trudge around a swamp with my toes hanging out. I ordered a new pair of proper boots too, but they still haven't arrived yet.\n\nOh well, pleasure doing business with you. I'll keep these for later!" }
