WordHunterWoW_QuestEN[96609] = { title = "A Taste of Home", description = "Are you familiar with Silvermoon Shimmerwine? It has a delicate flavor that is entirely unique to the vineyards of Eversong and it is the one thing I truly miss from my homeland.\n\nUnfortunately, it is extremely hard to find on this side of the Thalassian Gate.\n\nI had a patron bring me a bottle that he claimed to have \"liberated\" from blood elves in northern Azshara. If your adventures take you to that region and you can recover more bottles for me, I would handsomely reward your efforts.", objectives = "Bring 10 bottles of Silvermoon Shimmerwine to Arille Azuregaze in Dalaran city." }
WordHunterWoW_QuestEN[96616] = { title = "Herbs for the Bruised and Weary", description = "Could this be? Travelers have returned to Hyjal!\n\nI can hardly believe it! Perhaps with your aid we will finally be freed of this place. With the Scourge remnants to the east we have been subject to constant raids and many have fallen victim to their corruption.\n\nPlease, {class}. I would ask a favor of you. In the valley north of here grows an herb with blue flowers that can alleviate the pains of the infection. Gather some and bring it to me so I may help the wounded.", objectives = "Collect 12 Hyjal Silphium." }
WordHunterWoW_QuestEN[96622] = { title = "A Rest Without Pain", description = "I would ask one last favor while I have you here, friend. Could you deliver the poultice I have made to two of my companions here in camp?\n\nEnho is in our infirmary to the left. He is very weak but I yet hope he will be able to overcome the infection. I have been spoon-feeding him broth to try to help him regain his strength.\n\nThe other is Maruke.\n\n<Ortak hangs his head in silence for a moment.>\n\nYou will find her north of here, where we keep the few mounts we have left.", objectives = "Deliver the Hyjal Silphium Poultice to Enho and Maruke." }
WordHunterWoW_QuestEN[96626] = { title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", objectives = "Speak with Tomas in Goldshire to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills." }
WordHunterWoW_QuestEN[96627] = { title = "The Adventurer", description = "{name}, you have proven your competence as a protector thus far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Goldshire. Go and see what he's doing.", objectives = "Speak to Sam Sarsparilla near Goldshire.", completion = "I appreciate the lookin' out, {class}. That marshal's just a worrywart.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?" }
WordHunterWoW_QuestEN[96628] = { title = "The Adventurer", description = "Wait, {name}. I have another ask of you, before you brave that tunnel.\n\nMy mountaineers have reported an adventurer that's shown up just outside of Kharanos. Could you deliver these supplies to him?", objectives = "Deliver the Supply Bundle to Eric Brighthammer near Kharanos.", progress = "Are you here to learn about camping in the wilderness?", completion = "You say these are from the mountaineers? Aye, I could use them. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?" }
WordHunterWoW_QuestEN[96629] = { title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", objectives = "Speak with Gremlock Pilsnor in Kharanos to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills." }
WordHunterWoW_QuestEN[96630] = { title = "The Adventurer", description = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>", objectives = "Bring the journal to Lyreena Duskblade near Dolanaar.", progress = "Are you here to learn about camping in the wilderness?", completion = "Is that my journal? I've been missing this for a while. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?" }
WordHunterWoW_QuestEN[96634] = { title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", objectives = "Speak with Zarrin in Dolanaar to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills." }
WordHunterWoW_QuestEN[96638] = { title = "The Adventurer", description = "More and more adventurers like yourself have been seeking glory and fortune outside of the safety of Thendal Grove. There's one such adventurer who has made a camp outside of Shen'dar Village, along the road leading southwest out of Thendal Grove.\n\nSeek him out and see what you can learn from him that may help you in your own travels.", objectives = "Speak to Raan Wildwind near Shen'dar Village.", completion = "Well met!" }
WordHunterWoW_QuestEN[96646] = { title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", objectives = "Speak with Zerril Softbreeze in Shen'dar Village to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills." }
WordHunterWoW_QuestEN[96652] = { title = "The Adventurer", description = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>", objectives = "Bring the journal to Brakk near Razor Hill.", progress = "Are you here to learn about camping in the wilderness?", completion = "Is that my journal? I've been missing this for a while. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?" }
WordHunterWoW_QuestEN[96655] = { title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", objectives = "Speak with Cook Torka in Razor Hill to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills." }
WordHunterWoW_QuestEN[96656] = { title = "The Adventurer", description = "{name}, you have proven yourself trustworthy in your endeavors against the Scarlet Crusade so far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Brill. Go and see what she's doing.", objectives = "Speak to Eleanor Shackleton near Brill.", completion = "I'm not affiliated with the Scarlet Crusade, if you couldn't tell. I'm just an adventurer stopping by before my next venture into the wilderness.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?" }
WordHunterWoW_QuestEN[96658] = { title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", objectives = "Speak with William Pickman in Brill to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills." }
WordHunterWoW_QuestEN[96659] = { title = "The Adventurer", description = "Wait, {name}. I have another ask of you, before you leave us.\n\nThere is an adventurer by the name of Kaga Wildhoof who has made camp just outside of Bloodhoof Village. She has greatly helped me in the past, and now I see my chance to repay her. Could you deliver these supplies to her?", objectives = "Deliver the Supply Bundle to Kaga Wildhoof near Bloodhoof Village.", progress = "Are you here to learn about camping in the wilderness?", completion = "Chief Hawkwind sent you? I told him back then I needed no compensation, but it seems he hasn't listened. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?" }
WordHunterWoW_QuestEN[96661] = { title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", objectives = "Speak with Pyall Silentstride in Bloodhoof Village to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills." }
WordHunterWoW_QuestEN[96666] = { title = "Burrow Bonding", description = "Barkskin speak more good on you, friend, but there is yet more for you to do.\n\nRaise your hand to our foes. Honor our ways.\n\nWe watch close, and then we will have more to say to you.", objectives = "Raise your reputation with the Barkskin Burrow to Friendly." }
WordHunterWoW_QuestEN[96674] = { title = "Ewe Wandered Off", description = "<Mirt's eyes grow wide as you approach.>\n\nWhoa, who are you? My mom said there was a new person here. She said you killed a lot of Scourge and are super strong! Have you ever fought a bear? *gasp* A DRAGON!? I--\n\n<Mirt looks behind himself, then looks bashful.>\n\nMaybe... you could help me? I was supposed to be watching the sheep but they got out when I was making mud dragons. They are over on THAT side. I'm not allowed to go over there. Mom says they might hurt me. Could you go find the sheep?", objectives = "Capture and return 6 Escaped Sheep." }
WordHunterWoW_QuestEN[96676] = { title = "Unsealing Blackthorne Pact", description = "Well, informant, you're being promoted.\n\nTake these updated orders to Johun at his base camp in Hyjal. There's some additional equipment in here that he'll be needing for our operations in the Summit.\n\nYour assistance in these matters is pivotal to our overall strategy in Kalimdor, {name}. Tarry not.\n\nYou are dismissed.", objectives = "Bring the Alliance Equipment to Johun \"Punchy\" Dillas in Hyjal." }
WordHunterWoW_QuestEN[96735] = { title = "Toast!?", description = "", objectives = "" }
WordHunterWoW_QuestEN[96770] = { title = "The Witch Doctor's Head", description = "There exists a troll witch doctor that goes by the name of Zum'rah. I have history with this particular troll, and I'd like you to kill him for me.\n\nGo to the Sandfury stronghold of Zul'Farrak, deep in the deserts of Tanaris. Find Zum'rah inside and destroy him. Bring his head to me--intact--and I'll see that you are fairly compensated.", objectives = "Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Archmage Lan'dalock in Dalaran." }
WordHunterWoW_QuestEN[96771] = { title = "Vengeance of the Highborne", description = "In the region known as the Riverglades to the southeast, there is a place called the Krol'dok Stronghold. A highborne known as Zalfan Moonshadow has been seen there in the company of the Twilight's Hammer.\n\nI'd pay handsomely if you'd rid the world of this cretin for me. He brings shame to the proud lineage of the highborne by consorting with fanatics and using stolen arcane knowledge in their service. There are few enough of us left without worms like him sullying our good name.", objectives = "Travel to Krol'dok Stronghold and slay Zalfan Moonshadow." }
WordHunterWoW_QuestEN[96772] = { title = "The Dragon's Journal", description = "Timear and I have been scrying the area on Kalimdor known as Alcaz Island and we've all but confirmed the presence of a powerful magic user there. The mage in question was able to dispel our probes, but before she did, I was able to glean an image of a tome of some sort. I believe it was a journal, written in ancient draconic script.\n\nI don't know what is in that book, but I'd like to study it. We want you to travel to the hidden prison beneath Alcaz Island and recover that book for us.", objectives = "Recover Zarla's Journal from the depths of Alcaz Prison." }
WordHunterWoW_QuestEN[96773] = { title = "The Coldbringer's Eye", description = "There is a servant of the Lich King that makes his home deep in the quilboar lair known as Razorfen Downs. It is known to us that he makes use of a scrying orb known as \"The Coldbringer's Eye\" to direct the movements of his lesser minions elsewhere.\n\nGo into Razorfen Downs and retrieve the Coldbringer's Eye on our behalf, {class}. The Kirin Tor would pay handsomely to obtain this artifact so that we may study it and understand its inner workings.", objectives = "Recover The Coldbringer's Eye from Razorfen Downs." }
WordHunterWoW_QuestEN[96774] = { title = "Ancient Gurubashi Idol", description = "The ancient Gurubashi of Stranglethorn Vale were da masters of dark blood magics. Rumors be they'd use pure truesilver idols to channel that bad bad voodoo.\n\nOl' Mazu'kon would love to get his hands on one of those idols... for academics ya see. How 'bout you gather some friends and do a bit of smash and grab on that drowned city stickin' out the ocean off the coast of Stranglethorn? Kill the most impressive lookin' priest ya can find in there, and they sure to have what I be lookin' for.", objectives = "Recover an Ancient Gurubashi Idol from the Drowned City." }
WordHunterWoW_QuestEN[96775] = { title = "Zum'rah's Head", description = "Ol' Mazu'kon got a bone to pick with a Witch Doctor that go by the name of Zum'rah and I be thinkin' you can help me out with that. \n\nZum'rah practice all his bad voodoo in the Sandfury city of Zul'Farrak, far to the south in the deserts of Tanaris. Go there. Kill Zum'rah, and bring me his head.\n\nTrust me mon, the world be a better place with his head stuck on pike outside my hut than it be sittin' on his shoulders.", objectives = "Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Mazu'kon in Mulgore." }
WordHunterWoW_QuestEN[96776] = { title = "An'she's Radiance", description = "I have had a vision.\n\nDeep in the place known as Maraudon, past the earth song falls, there is a chamber filled with brilliant white crystals and guarded by mighty giants. At the highest part of this chamber is a crystal of exceptional brilliance. It is an aspect of the sun god, the right eye of the Earthmother herself--An'she.\n\nI've dreamed of its radiance and it calls to me. {class}, remove An'she's Radiance from that place and bring it here where it belongs, under the open skies of Mulgore.", objectives = "Recover the crystal known as An'she's Radiance from Maraudon." }
WordHunterWoW_QuestEN[96779] = { title = "Syndicate Sabotage", description = "Sometimes, {race}, a single cut in the right place will drop a foe dead. The same is often true of organizations.\n\nOur agents have identified a key target among the ranks of the Syndicate: a man by the name of Lord Tomas.\n\nHe plays an instrumental role in the functions of Durnholde Keep, in Hillsbrad Foothills. If you wish to be of service to Ravenholdt, go to Durnholde and eliminate him. The quicker, and quieter, the better.", objectives = "Find Lord Tomas inside Durnholde Keep, in Hillsbrad Foothills, and kill him. Then, return to Myrokos Silentform." }
WordHunterWoW_QuestEN[96781] = { title = "What's the Big Idea?", description = "We have noticed a Syndicate scouting party prowling around the ruins of Alterac, led by a man named Barton.\n\nThey're clearly searching for something, but I cannot know what without reading his scouting reports.\n\nI ask that you pickpocket the report from him, rather than killing him outright. Barton's death will tip off the Syndicate that we're on to them, and they will certainly take counter-measures to cover their tracks.\n\nIf you hope to find him, he is most likely among the Syndicate at Strahnbrad.", objectives = "Steal Barton's Scouting Report by pickpocketing it from him. Then, bring the report to Myrokos Silentform at Ravenholdt Manor." }
WordHunterWoW_QuestEN[96782] = { title = "Covert Extraction", description = "It seems our friend Barton here has made this very easy for us. He is after two heirlooms of the Perenolde family within the ruins of Alterac. The Blade of House Perenolde, a sword, and the Royal Aegis of Perenolde, a shield.\n\nFrom the report, it seems these armaments are within two towers among the ruins. Best we acquire them before the Syndicate does.\n\nThe ogres occupying the ruins are fierce, but I trust you should be able to sneak past them without needing to bloody your blade at all.", objectives = "Find the Blade of House Perenolde and the Royal Aegis of Perenolde among the ruins of Alterac. Then, bring them to Myrokos Silentform." }
WordHunterWoW_QuestEN[96783] = { title = "A Way In", description = "Stromgarde Keep is one of the Syndicate's largest strongholds. Many of the organization's most important dealings take place behind its walls.\n\nI have received word of a certain trade taking place between members of the Syndicate somewhere in Arathi Highlands, and I'm certain the details of this trade can be found somewhere in Stromgarde.\n\nTo infiltrate the keep without arousing suspicion, you'll need a disguise. See if you can find one among the Syndicate outside the keep, at Northfold Manor.", objectives = "Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep." }
WordHunterWoW_QuestEN[96784] = { title = "Master of Disguise", description = "<You recall Myrokos' instructions to find out about an important deal going on with the Syndicate in Stromgarde Keep. With your disguise, you should be able to talk to members of the Syndicate somewhat freely. Surely, one of them knows something.>", objectives = "While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal." }
WordHunterWoW_QuestEN[96785] = { title = "Ain't No Telling", description = "Who do you think you are? Showing up and sticking your nose in official business.\n\nI'm not telling some rookie anything about the higher-up's dealings without good reason. Unless you've got something important, or valuable, for me, I've got nothing to say to you.", objectives = "Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal." }
WordHunterWoW_QuestEN[96786] = { title = "The Syndicate Sting", description = "Falconcrest sent some guys to do a handoff at the southern part of Thoradin's wall. I don't know what they're picking up. Must be good, because everyone involved has kept it a total secret. I don't think the guys picking it up even know what it is.\n\nThat's all I've got. Don't make me regret telling you that.", objectives = "Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor." }
WordHunterWoW_QuestEN[96796] = { title = "Woods Workshop", description = "This looks like something that the tinker in the hills, Kaylaena, could make use of. She barely visits ever since the loss of her mentor, Yaely.\n\nLook for her workshop in the hills to the north. After Archimonde's fall in the great battle, the two of them scavenged what they could easily bring back themselves, picking many of the machines on these foothills clean.\n\nPutting this debris to new use is better than allowing it to rust here. Your errand helps new life sprout where it was choked by metal.", objectives = "Bring the Spare Part to the tinker known as Kaylaena in lower Hyjal." }
WordHunterWoW_QuestEN[96797] = { title = "The Orphan", description = "We often try to find surviving family for many of our charges, and occasionally we find something hopeful. I've received word that Randal here may have a surviving family member. The man's name is Danneth, and he is a soldier stationed at Nethergarde Keep. I need someone to travel there and find the man.\n\nIf you can, please convince Danneth to come retrieve his nephew. I don't think the two have ever met, but they are family all the same and Randal belongs with him.", objectives = "Travel to Nethergarde Keep in the Blasted Lands and locate Sergeant Danneth." }
WordHunterWoW_QuestEN[96798] = { title = "Into the Darkness", description = "Sergeant Danneth was last seen on patrol with his squad near Serpent's Coil, just south of Nethergarde Keep. One of the members of his squad stumbled back into the keep, badly wounded and claiming that the entire squad was killed or captured. That soldier died a few hours later, unfortunately.\n\nWe don't have confirmation that Danneth is dead, but chances aren't good. I can't spare the men to push into the cult's lair, but if you wanted to go and look for the man, I'd not refuse the aid.", objectives = "Find Sergeant Danneth somewhere in the Serpent's Coil caverns southeast of Nethergarde Keep." }
WordHunterWoW_QuestEN[96799] = { title = "A Heavy Responsibility", description = "<Lieutenant Connar listens as you tell him the reason you are here.>\n\nSo, Danneth has an orphaned nephew in Dalaran? If you haven't spoken to him about this yet, I'd suggest you do so. He doesn't exactly seem like the parenting type, but he might surprise me.\n\nIf he does want to go and collect the boy once he's recovered, he has my blessing to take leave for that.", objectives = "Speak with Sergeant Danneth at Nethergarde Keep." }
WordHunterWoW_QuestEN[96800] = { title = "Past Due", description = "You there, {class}. I have a matter I could use assistance with.\n\nI just so happen to be writing a thesis on the ancient Wildhammer runemasters of Grim Batol, and there's a particular tome I need to complete my research. According to our ledgers, a mage by the name of Doan checked the book out of the old Dalaran library before the Third War and never returned it!\n\nArcanist Doan is now holed up in the Scarlet Monastery in Tirisfal Glades. Retrieve this book for me and you'll be well rewarded.", objectives = "Retrieve the book The Lost Magic of the Runemasters from the Scarlet Monastery." }
WordHunterWoW_QuestEN[96811] = { title = "Escaping the Shadows", description = "I think I'm ready now. Let's get going when you are ready.", objectives = "Escort Sergeant Danneth out of the Serpent's Coil caves and back to Nethergarde Keep." }
WordHunterWoW_QuestEN[96812] = { title = "Thicker Than Water", description = "Yes... yes, I will take the boy in. He is family and I'm all he has. I need to recover for a bit longer, but I'll be taking leave and heading to Dalaran as soon as I am able. \n\nPlease return to the Matron and let her know that I am on my way. I'll do my best to ensure that my brother's child is kept safe and grows up strong.\n\nI swear it.", objectives = "Return to Orphan Matron Aria in Dalaran and inform her of Sergeant Danneth's intentions to take in Randal." }
WordHunterWoW_QuestEN[96821] = { title = "Legging It", description = "We see fewer and fewer travelers from Razor Hill these days. The scorpids were never much fun, but now I hear there are spiders making their nest along the road.\n\nIf your travels take you up north, kill some of the spiders on your way. Then, let Razor Hill know the path's a bit safer for them.", objectives = "Kill 6 Ridgeshade Creepers and 6 Ridgeshade Lurkers in southern Durotar, then report to Gar'thok in Razor Hill.", completion = "The peons have been scared to travel south for some time, {name}. Now that you've cleared the path a bit, we can get them back to work." }
WordHunterWoW_QuestEN[96822] = { title = "For Honor", description = "We lost many brave warriors of the Horde when we sacked Tiragarde Keep. Now that the humans have reinforced the ruins, we cannot collect their remains to properly honor their deaths.\n\nGo to the ruins surrounding the keep, and search for the weapons left by our fallen kin. We will display them in a place of honor.", objectives = "Collect the Raider's Battleaxe, Raider's Bow, and Raider's Shield from the Tiragarde Keep outskirts, then return them to Turroc in Razor Hill.", progress = "Have you done what I asked?", completion = "These warriors will always be remembered, {name}. You have made sure of that." }
WordHunterWoW_QuestEN[96825] = { title = "This Fruit Could Bite Back", description = "Our hunters and fishers bring back plenty of savory food for our troops - but it's rare that they get a sweet treat.\n\nI've seen a cactus that produces a prickly, tasty fruit. But it only grows in the hills to the west, where the wretched quilboars make their camps. Make your way past the quilboars and bring me some of those fruits. And be careful - the fruits are as spiny as the quilboars!", objectives = "Cook Torka in Razor Hill wants you to collect 8 Prickly Pear Fruit from the Razormane Grounds west of town.", progress = "Did you find the fruits?", completion = "I'll use these to prepare something tasty, and save the seeds for planting. Someday we'll have prickly pears growing all around Orgrimmar!" }
WordHunterWoW_QuestEN[96830] = { title = "Farsight Guided", description = "My axe still bled demon gore when I heard a human screaming high above.\n\nI looked up and saw this man dangling in the claws of a great chimaera. He fought back fiercly causing the beast to lose its grip and drop him. \n\nFrom that height, no warrior walks away. Even enemies deserve dignity, so I dragged him into the shade to pass in peace.\n\nFor my part, I track the farseers' visions--friends remain in Hyjal, far northwest.\n\nFind the remaining Horde in my stead. Honor requires me here.", objectives = "Look for signs of Horde in the northwest of Mount Hyjal." }
WordHunterWoW_QuestEN[96833] = { title = "Venom Maws", description = "Gh... Ghan. Sur... Okk... Ghansurok. That's the fel chimaera's name. I thought I could manage out here... ugh... alone. No chance. Picked me clean into the air.\n\nStuck my dagger through its closest eye I could find, and I fell farther than the tree tops.\n\nI wasn't the only one who bit off more than I could chew this time. Haha--agh... I shouldn't make myself laugh, this hurts bad enough.\n\nBroken bones we could mend, but... the venom... is too vile.\n\nPass on a warning. I beg you!", objectives = "Pass on the warning of the aggressive chimaera known as Ghansurok to others on the mountain." }
WordHunterWoW_QuestEN[96873] = { title = "A Pain in the Neck", description = "The trolls east of here have lost their will to the witchdoctor, Zalazane. He uses many cruel magics to keep hold of his prisoners' minds, but one of his favorite tricks is to make them wear pendants wrapped in evil binding spells.\n\nPractice your enchanting skills by stripping the magic from these pendants, and bring me the results. And don't accidentally put one around your neck, if you value your freedom!", objectives = "Pa'zula in Sen'jin Village wants you to collect 3 Luminous Residue. Luminous Residue can be obtained by disenchanting Hexed Pendants dropped by trolls in the Echo Isles.", progress = "What do you have for me, {name}?", completion = "Fine work. A shame about the slain trolls, but with the binding spells removed, their spirits can rest." }
WordHunterWoW_QuestEN[96874] = { title = "This Is Spinal Axe", description = "Have you seen the huge beasts of Thunder Ridge? I keep thinking the spines on their backs would be perfect for crafting the head of a mighty axe. Saru laughed when I told him... but what does he know!?\n\nAs part of your smithing lessons, you can help me out! Bring me some of those spines, along with grinding stones to sharpen them.", objectives = "Ug'thok in Orgrimmar wants you to collect 5 Weathered Spines from beasts in Thunder Ridge, along with 5 Rough Grinding Stones.", progress = "Yes?", completion = "These spines are tougher than I expected, {name}! Crafting with them may not be as easy as I thought... but I'll keep working on it!" }
WordHunterWoW_QuestEN[96875] = { title = "Beasts of Thunder Ridge", description = "Orgrimmar is always expanding, {class}. And when the peons need hides to line the walls and roofs of our new buildings, they come to me!\n\nThe hides of the lizards in Thunder Ridge are typically too thick for armor, but they make excellent building material. Bring me some of their hides, along with a few lighter cured hides. Let's see your skill with leather!", objectives = "Kamari in Orgrimmar wants you to collect 5 Rough Lizard Hide from beasts in Thunder Ridge, along with 2 Cured Light Hides.", progress = "Yes?", completion = "Your work helps Orgrimmar grow. Know that as you walk the city's paths." }
WordHunterWoW_QuestEN[96876] = { title = "Ukor's Lost Pack", description = "The pack has the name \"Ukor\" crudely stitched along the flap.", objectives = "Return the pack to Ukor in southern Durotar.", progress = "Something need doing?", completion = "My pack! When I dropped it to run from that huge spider, I thought I'd never see it again. You really are a hero!" }
WordHunterWoW_QuestEN[96877] = { title = "Halikor's Hoof", description = "The enormous hoof serves as proof of your victory over the mighty lizard.", objectives = "Deliver Halikor's Hoof to Orgrimmar.", progress = "Yes?", completion = "What a trophy, {class}! That must have been some fight!" }
WordHunterWoW_QuestEN[96895] = { title = "The Argent Emissary", description = "Not sure if you heard, but two emissaries of the Argent Dawn just passed through here. I don't mind the Argent Dawn, but I don't like them poking around Tirisfal unsupervised either. They were both Forsaken... but that doesn't make me any less nervous.\n\nOne of them just passed by here, headed southeast. There's a group of scourge cultists snooping around the outskirts of the city in that direction. If those two heard about them, there's no doubt that would have caught their attention.", objectives = "Find the Argent Dawn member near the entrance to the Undercity.", completion = "Stay low and try not to be seen, {class}. These cultists are not to be trifled with." }
WordHunterWoW_QuestEN[96896] = { title = "A Righteous Cause", description = "Danitha and I fought against the Scourge in the defense of the Undercity when Naxxramas attacked. We lost many good friends that day, including the hero after which this keep was named--Garek Bandarion.\n\nHe might just have been the first Forsaken to rediscover how to wield the Light as a paladin. I am encouraged to see his legacy and potential live on here with Danitha and her cohort.\n\nIf only the rest of the Forsaken felt the same way...", objectives = "Observe the conversation between Danitha Morr and Leonid Barthalomew the Revered.", completion = "I plan to stay here for a time and speak with more of my friends, but I will return to Light's Hope Chapel in Eastern Plaguelands soon enough. Should you ever find yourself out that way, please do say hello. We could always use more help from able-bodied adventurers." }
WordHunterWoW_QuestEN[96897] = { title = "The Cult of the Damned", description = "The Scourge are a blight on our lands, and their living servants are the worst of them. The people of Tirisfal have enough to deal with between the mindless dead and the Scarlet Crusade. If you wish to do some good, help me put an end to this scum.", objectives = "Kill 8 Dark Neophytes and 8 Dark Enforcers in Tirisfal Glades.", completion = "Thank you for your aid, {class}. If we do not wish to see Lordaeron's history repeat itself, we've got to be vigilant when threats like this spring up." }
WordHunterWoW_QuestEN[96898] = { title = "Remnants of War", description = "It wasn't long ago that the citadel of Naxxramas bore down upon this city, intent on wiping the Forsaken off the map. Both the Forsaken and the Argent Dawn lost much that day to secure the future of the Forsaken.\n\nDuring the battle, the great necrotic focusing crystal mounted atop Naxxramas was shattered and its fragments were scattered all over this area. I suspect that is what the cultists are here for. Help me recover the fragments and deprive the Scourge of them.", objectives = "Gather 12 Necrotic Crystal Fragments in Tirisfal Glades.", progress = "I'd advise you not come into too much physical contact with those crystals. Even shattered and spent, the lingering magic in these necrotic crystals is highly dangerous.", completion = "Thank you. This should slow the efforts of the Scourge in this area. I suspect the denizens of Tirisfal will be pulling these crystals out of the ground for years, but removing the most conspicuous of them can only help." }
WordHunterWoW_QuestEN[96899] = { title = "Bandarion Keep", description = "You've done a great thing for the cause of the Argent Dawn here today, and I thank you. I don't know how familiar you are with the fortress of Bandarion Keep, but my commander and I were headed that way to meet with the paladins that reside there. That was before we learned of the presence of the Cult of the Damned.\n\nIf you'd like to learn more about the Argent Dawn and our mission, seek out my commander at Bandarion Keep, to the northwest of here. I'll remain here to mop up the rest of this mess.", objectives = "Meet Leonid Barthalomew at Bandarion Keep in Tirisfal Glades.", completion = "This place is full of memories for me. This place was once held by the Argent Dawn. It was from here that we prepared for many battles and skirmishes against the Scourge during their most recent push into Tirisfal Glades.\n\nWhen we withdrew to the Plaguelands I feared it would fall into disrepair. My fear was well-founded, but I am glad that Danitha and her paladins have taken over stewardship of it now.\n\nShe even named the keep after... a mutual friend." }
WordHunterWoW_QuestEN[96912] = { title = "Field of Honor: Week 1", description = "Heya pal, step right up! You look like you know which end of the sword goes where! \n\nIt just so happens that I have a long list of challenges that only the most elite fighters will be able to accomplish. Wanna take a stab at it?", objectives = "Win 10 duels." }
WordHunterWoW_QuestEN[96913] = { title = "Field of Honor: Week 2", description = "You again, eh? Ready for the next test? I hope you aren't squeamish. You might need to bleed for this one... or preferably make the other guys bleed first.", objectives = "Complete 3 Warsong Gulch battles." }
WordHunterWoW_QuestEN[96930] = { title = "The Capricious Corvid", description = "We need powerful magic indeed to counter the strength that Ve'han Talongrasp now commands. The staff Velician snatched might just be the key.\n\nMy powers as a druid are not what they once were. We will need aid from the divine denizens of the mountain in order to stop this evil.\n\nReturn to the crow you met up the mountain. She is wise but the spirits of the wilds are ever-capricious, even in the face of dire threats. She may be challenging, but we will need her help.", objectives = "Return to the Curious Crow." }
WordHunterWoW_QuestEN[96931] = { title = "Heading Up the Mountain", description = "Listen, dirtwalker. I am, of course, known for my intellect and wit but there is one that is even more majestic and powerful than I.\n\nNaturally, I am speaking of cleverest, most cunning, and comely of the Wild Gods, Jereman! Every bird knows her name, and she is wise beyond her wingspan. She certainly will know what is needed for that oldstone's magic.\n\nShe nests up in what you dirtwalkers call the Cradle of Tranquility. Touch the crow effigy on the old bridge and she may appear!", objectives = "Touch the Crow Effigy on the bridge overlooking the Cradle of Tranquility to call the Wild God, Jereman." }
WordHunterWoW_QuestEN[96939] = { title = "The Balance of Life and Death", description = "I believe one of my good friends may have an idea for an additional source of power for Ketharas's gambit.\n\nHe is close friend, of course, and he will be thrilled to lend his aid to an agent of my will such as yourself!\n\nYou can find that old stinkfeather in the area south of here that is crawling with undead. Mourning's Rest I think you mortals call it?\n\nMake sure you mention that I sent you! He will LOVE that... most certainly!", objectives = "Speak to the Wild God, Marrosis." }
WordHunterWoW_QuestEN[96957] = { title = "Bone Sweet Bone", description = "Listen, mortal. Though it may not appear a glorious job, those that are under my wing help keep the natural balance. We return many essential nutrients to the soil, allowing for new life.\n\nThese undead have disrupted the cycle here and have driven off those that seek shelter under my wings. While you are out there being the little murderous creature you are, would you collect some bones for me?\n\nI would like to rebuild the nests of my children and followers so we may feast when this blight has ended.", objectives = "Collect 20 Sun-Bleached Bones." }
WordHunterWoW_QuestEN[96959] = { title = "Blademaster's Bonfires", description = "War.\n\nBy the time I heeded the call of our clans, the battle had passed, and only ashes answered my blade.\n\nMy purpose is forged anew.\n\nThis mountain remembers strength--ancient power riding its winds and holding its water. I would earn the right to walk its spine, to reach the fallen stronghold that lies upon the road to the summit.\n\nDemons profane these graves. Before I fight at your side, I must know you stand capable. Light the two bonfires and return to me. Their flames draw our enemy out.", objectives = "Light the two bonfires in Dae'gun and return to Yashiro." }
WordHunterWoW_QuestEN[96964] = { title = "A Clever Creature", description = "If the hermit truly wants his little gambit to leave the nest and fly, it will likely need a potent energy source. One that can sustain itself without collapse.\n\n<Jereman looks to the sky and clacks her beak together as she considers.>\n\nAh, yes. I know just the clever creature we can consult. Go north into the area you mortals refer to as Dae'gun, the one with the demons, and seek out the fox Wild God Renalard. I believe he will have a solution to our little puzzle.", objectives = "Speak to the Wild God Renalard." }
WordHunterWoW_QuestEN[96971] = { title = "To Outfox a Demon", description = "Say, while you're out and about prancing in my lands, would you mind doing me a favor?\n\nOnce the war had been won, many of the various armies up and left. For whatever reason, they decided some of their supplies were not worth taking. That, or they all died. Who could say?\n\nRegardless, these supplies are of use to my kits and me. Unfortunately they also tend to be where the demons are. Take this tuft of fur with you and use it on the demons to distract them while you grab the tools.", objectives = "Collect 8 Abandoned Supplies." }
WordHunterWoW_QuestEN[96978] = { title = "Violent Venison", description = "Ever since those nasty Blackthorne druids came to power many of the less powerful gods here on Hyjal have... well to be blunt they've attempted to upend the natural order of things.\n\nThe very worst offender of this is Kala'th.\n\n<Jereman rolls her eyes.>\n\nThat silly deer seems to fashion herself and her herd as predators. Again.\n\nDon't get me wrong, it was quite amusing at first, but now it is time we get things back in wing.\n\nGo speak to her to see if you can bring her back to reason, please.", objectives = "Speak to the Wild God, Kala'th." }
WordHunterWoW_QuestEN[96979] = { title = "Sacred Refreshment", description = "I am a druid of the Circle, walking the long path to honor the great world tree. I misjudged how much the climb would ask of me, and the winged hunters that haunt these slopes have made caution a necessity. These old ruins offered shelter, and I accepted it.\n\nThis place is suitable for a humble offering, yet no ritual should be given without living water. If you would, fill my gourd at the falls ahead. \n\nWhen you return, speak to me of the trail you walked, and of what stirs upon it.", objectives = "Fill Galvinquam Leafsyre's drinking gourd at the waterfall ahead." }
WordHunterWoW_QuestEN[96982] = { title = "Your First Riding Kodo", description = "Ah, I've been expecting you, {class}. It would seem the winds have brought you to me this day. You have come seeking a kodo, correct?\n\nThe kodo is a noble beast that is slow to anger, and you would be hard pressed to find a more dependable companion.\n\nToday you have an important choice to make. You and your kodo will travel the world together, so find which one speaks to you. Fear not, whatever choice you make will be the right one.\n\nGo examine the kodos and return to me when you have made your choice.", objectives = "Inspect the riding kodos to choose your first mount." }
WordHunterWoW_QuestEN[96983] = { title = "Yashiro's Windwalk", description = "You're capable, fast, fearless. Fire will draw the demons from their hiding places, and with them, their warlords. They will come seeking dominance. Instead, they will find vengeance waiting. This is the moment where the will of the mountain speaks through us.\n\nCome, let us carve a path through these hellspawn and end their reign. My blade yearns to cleave through their ranks.", objectives = "Fight your way through Dae'gun with Yashiro." }
WordHunterWoW_QuestEN[96984] = { title = "Heart of Disruption", description = "You may not have our best interests at heart, but I won't deny an extra pair of hands. And if Dalaran falls, it takes everything with it--including your Undercity.\n\nSo, your benefactor wants in? Fine. I'll imbue your key to work past my wards so you can enter the city. Once you're in, meet me at the Violet Citadel where this all began. With everything going on the Kirin Tor will be too busy to stop you.\n\nScavenge what you will, but whatever happens, our first priority is to prevent a catastrophe.", objectives = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", progress = "You were right to come straight back to me. Have you found anything in Dalaran?", completion = "Oh my, a shade of the archmage? How utterly embarrassing for them.\n\nAnd the Kirin Tor allowed you into their inner chambers? Interesting. This could provide an opportunity..." }
WordHunterWoW_QuestEN[96986] = { title = "The Grave Knight", description = "Within the underbelly of the mage city to the north is a traitor to our kind. A necromancer of disturbing talent. He raises an army of undeath right under the Kirin Tor's nose.\n\nI care not for the fate of the mage city, {name}, but this grave knight spits in the face of everything we Forsaken stand for. Put an end to him. Show him no one is beyond the reach of the Dark Lady.", objectives = "Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill.", completion = "Excellent work. That beast is unworthy to walk among the dead. Let him lie beneath them." }
WordHunterWoW_QuestEN[96987] = { title = "Opportunistic Education", description = "Well if it ain't a like-minded entrepreneur. Sneakin' into Dalaran durin' such troublesome times? Tsk tsk.\n\nMy kinda {race}!\n\nWhile our mage friends here are occupied, maybe we could find ourselves some 'misplaced' treasures. They gots whole libraries dedicated to fancy arcane magics. If you could bring me one of their secret tomes, I could sell it for a pretty penny. Split the profits with ya.\n\nHey hey don't look at me like that. You ain't exactly here on a field trip yourself. You want in or what?", objectives = "Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance.", progress = "Well? Didja find their library? There's gotta be somethin' good in there.", completion = "I guess I shouldn't have sent a stooge to look for priceless artifacts. This is barely worth sellin' at a tourist kiosk! What, did you just grab the first book that seemed to be jutting out from the rest?\n\nForget it. Maybe I can spray it with gold and say it belonged to an arch mage or somethin'." }
WordHunterWoW_QuestEN[96988] = { title = "Source of Power", description = "With the city of Dalaran under siege by their own constructs, this is the perfect opportunity to, let's say, borrow a few samples.\n\nImagine an army of arcane-powered abominations. The Dark Lady would have no choice but to recognize my alchemical prowess. Maybe even grant me head of the Royal Apothecary Society?\n\nGo to the city and find the constructs' cores. They are unlikely to give them willingly, so do what you must.", objectives = "Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity.", progress = "The value in these cores is that they are powerful. The downside is that means the constructs are powerful. Good luck.", completion = "Cracked. Cracked. CRACKED.\n\nI can't make use of any of these! I said disable the sentries, not obliterate them! How dangerous could they have been?\n\nMy dreams of magus abominations are at a standstill. For now." }
WordHunterWoW_QuestEN[96989] = { title = "Your First Riding Raptor", description = "Ey mon! Today be a big day for ya, I see. Ya think you're ready to take de reins of one of these fierce creatures, huh?\n\nMost be underestimatin' how intelligent and savage these beasts be. Ya won't be findin' a better, faster or more lethal companion once ya be bonded with it.\n\nSo, you be havin' an important choice to make. Ya raptor and you will be traversin' the world together, and the raptor will also be needin' to choose ya in return.\n\nGo an' take a look and return to me when ya made ya choice.", objectives = "Inspect the riding raptors to choose your first mount." }
WordHunterWoW_QuestEN[96991] = { title = "Trail Assist", description = "The climb grows steeper from here, as you say. Even an empty pack weighs on tired legs. I would ask another kindness of you, traveler. Take my excess gear and carry it ahead to the Summit, where Marn Euhron aids in restoring a foothold near Nordrassil.\n\nI will follow at my own pace when my ceremonies here are complete. When I arrive, I will reclaim them from him and assist him in their work. This way, we both honor the journey and gifts of the mountain.", objectives = "Deliver Galvinquam's Belongings to Marn Euhron in the Summit." }
WordHunterWoW_QuestEN[96992] = { title = "Resupply", description = "You know, they packed enough tools to get the essentials started, but there's never enough fastening material. Only so much cordage-winding my hands can take.\n\nResourcefulness is even better than being prepared.\n\nTake an empty bag to the burned-down remains of the alliance buildings around the Cradle of Tranquility southwest of here, and fill it with as many nails and brackets as you can find in the ashes.", objectives = "Look through the burned buildings in the Cradle of Tranquility for 6 Metal Brackets and 30 Nails and return to Johun \"Punchy\" Dillas in Hyjal." }
WordHunterWoW_QuestEN[96994] = { title = "Your First Riding Wolf", description = "Lok'tar, {class}. Come to bond with your first wolf? Good.\n\nThere is no stronger bond than that of an orc and their wolf. They are no mere mount, but are a lifelong companion and friend.\n\nOurs is not a bond chosen by vanity. No, each orc and wolf forms a special bond that goes beyond a mere purchase.\n\nThey will choose you as much as you will choose them. You will understand when you meet them.\n\nGo and find which wolf speaks to you. Return to me when you have your answer.", objectives = "Inspect the riding wolves to choose your first mount." }
WordHunterWoW_QuestEN[96996] = { title = "Your First Riding Galestrider", description = "Now that you have completed your training, it would seem the winds wish you to bond with your first strider.\n\nThese galestriders have been ridden by our ancestors for generations. Despite their wispy and slender appearance, they are steadfast and fierce mounts.\n\nYou and your strider will traverse the world together, so you have an important choice to make. Fear not, whatever choice you make will be the right one.\n\nGo examine the striders and return to me when you have made your choice.", objectives = "Inspect the riding striders to choose your first mount." }
WordHunterWoW_QuestEN[96997] = { title = "A Steed in Death as They Were in Life", description = "Greetings, {class}. I imagine I can guess what has brought you to my stables today.\n\nIf you are looking for a mount, you have come to the right place. Be warned though, riding an undead steed is not for the faint of heart.\n\nAs such, you have an important choice to make. You and your undead steed will travel the world together for good or ill. Fear not, whatever choice you make will be the correct one.\n\nGo examine the undead horses and return to me when you have made your choice.", objectives = "Inspect the undead riding horses to choose your first mount." }
WordHunterWoW_QuestEN[96998] = { title = "Tribal Colors", description = "The skeleton still clutching a throwing spear has the telltale signs of a troll headhunter.\n\nIn one of its bony clutches is a wrap of leather adorned with troll characters and smudges of face tints in Darkspear colors. This must have been a makeup pouch used to apply war paint.\n\nDarkspear tribe members may recognize the writing on the sacred skins.", objectives = "Take the War Paint Wrap to someone who may recognize it." }
WordHunterWoW_QuestEN[96999] = { title = "Wrap Return", description = "Whoever wore dis fought wit' purpose. An' Sen'jin be a small village... blood an' kin run close dere.\n\nSomebody back home be missin' dis wrap--and da warrior who carried it.\n\nWhen ya trek to Echo Isles, take dis wrap wit' ya. Bring it home to Sen'jin. Dey'll know who it belong to--and dey'll honor ya for seein' it returned.", objectives = "Take the War Paint Wrap to someone in Sen'jin Village." }
WordHunterWoW_QuestEN[97000] = { title = "Grain of Memory", description = "Before this... second life, I learned the grain of wood in my father's shop.\n\nWhen war reached Hyjal, he stayed behind, crafting arms for those bound to the summit. I fled to Lordaeron. His final letter came from that mountain camp, and no word followed.\n\nMy death was likely no gentler than his. When I rose in Undercity, it felt like years had passed--but barely two had.\n\nYou look capable of the climb. Any remnant you find of my father, Lawrence Sawyer, would bring me solace.", objectives = "Search Hyjal's destroyed Alliance camps for signs of Abigail Sawyer's father, Lawrence." }
WordHunterWoW_QuestEN[97001] = { title = "Sawyer's Legacy", description = "Inside the wardrobe, a ledger records trades of hay, lumber, draft animals, and land. Other notes--personal and unfinished--are tucked between its pages.\n\nThe figures tell their own story: the Sawyer family was skilled at turning timber into weapons, tools, furniture, and wagons alike.\n\nThumbing through the pages reveals other kin of the family. Abigail Sawyer is listed among the relatives.\n\nShe would be very interested in this.", objectives = "Take the Sawyer Family Ledger to Abigail Sawyer in Undercity's War Quarter." }
WordHunterWoW_QuestEN[97003] = { title = "Chol'aruk the Ravener", description = "You there, {class}. I need your aid. There are rumors of a beast that makes its lair deep in a cave at Thorn Hill, northeast of here. The Razormane call it Chol'aruk or \"The Ravener\". It's supposedly five times the size of a normal quilboar with a thirst for blood that can never be sated.\n\nMost don't believe the tales. But I do--because I've fought its like before.\n\nSeek out its lair and slay Chol'aruk. Bring me its head. I warn you though--prepare well and do not go alone.\n\nBlood and thunder, {class}.", objectives = "Bring the head of Chol'aruk to Gur'ak in the Barrens.", progress = "It took the strength of six skilled fighters to defeat one of these creatures, and it still managed to fell four of us before we could put it down.\n\nIf these monstrous beasts were to appear in greater numbers, the damage that the quilboar could inflict upon the land could be catastrophic.", completion = "Impressive, {class}. None will doubt my tales when I return to Orgrimmar with this grim proof of the existence of these abominations. Rest assured this glory is yours however, and I will speak loudly of your deeds.\n\nLok-tar!" }
WordHunterWoW_QuestEN[97005] = { title = "Chol'aruk the Ravener", description = "There are rumors of a colossal abomination that makes its lair at a cave to the northwest of here, on the plateau known as Thorn Hill. The Razormane call it Chol'aruk or \"The Ravener\" and those that have seen it say it's so massive that it can swallow an orc whole.\n\nFew believe such tales, but I do... because I've fought one like it myself. On the honor of those I lost to these things, this beast must die.\n\nGather strong allies and find the lair of Chol'aruk. Kill the abomination and bring me its head.", objectives = "Bring Chol'aruk's Head to Bainham in the Barrens.", progress = "It took six of us to defeat one of these creatures, and it still managed to kill all but myself and one other before we were able to bring it down.\n\nThis far from alliance lands I should leave it well enough alone. Light knows I'll lose little sleep over a few tauren savages or orcish brutes. However, the honor of my fallen brothers demands action.", completion = "My dead men will rest easier knowing that there is one less of these monsters in the world. You've done well, and are a true and stalwart defender of the alliance. Thank you.\n\nGo with honor, {name}." }
WordHunterWoW_QuestEN[97006] = { title = "Notarized Claim", description = "I've added a note and my signature beside my name on the original page.\n\nTake it to Royal Overseer Bauhaus at the Undercity Census and explain where it was found. He must know how it came to me while I remained at my shop.\n\nYou can be honest and say to him that Abigail Sawyer told another stranger her sob story and you happened to actually have the means to follow up on it.\n\nAgain, thank you for doing this for my family.", objectives = "Take the Sawyer Family Ledger to Royal Overseer Bauhaus in Undercity's Trade Quarter." }
WordHunterWoW_QuestEN[97007] = { title = "Wood Remains", description = "I've stamped the pertinent pages for Abigail's records and updated our own documents.\n\nAbigail will have to send a follow-up to the Royal Census when she intends to transport any of the property into Forsaken territories.\n\nYou may return her ledger and bring with it a reminder: Her contractual obligations to the War Quarter's commissary are not yet fulfilled, so she would be prudent to wait before attempting to act on any of these pre-war ownership claims.", objectives = "Return the notarized Sawyer Family Ledger to Abigail Sawyer in the War Quarter." }
WordHunterWoW_QuestEN[97009] = { title = "Maerion's Misery", description = "Left bleeding and abandoned--thrown aside so an army could flee. I was meant to die buying them moments. \n\nInstead, I was cursed to endure, forced to watch ever-burning demons finish what steel could not. This is my fate.\n\nBut something is changing. Horde and Alliance return to this desecrated mountain, and war stirs again.\n\nMy fury answers it. \n\nIf yours does as well, prove it. Bring me two handfuls of felhound spikes from these Defiling Hounds.\n\nThe pain will align our wills.", objectives = "Bring 12 Felhound Spikes to Maerion Thaelemaches in Dae'gun." }
WordHunterWoW_QuestEN[97010] = { title = "Blind Vengeance", description = "The rune-etched shards are prepared. Dropped from high enough, they'll shatter upon impact, ripping through armor and demon flesh.\n\nThere's a tower overlooking this wasteland. It will give us the height we need.\n\nWe climb. I'll keep to the shadows and guard your flank.\n\nWhen we reach the top, signal me by making the first throw. I'll bring ruin down on them.", objectives = "Climb to the top of the Horde Mage Tower and throw an Explosive Runeshard to signal for Maerion Thaelemaches to launch his attack on the demons." }
WordHunterWoW_QuestEN[97017] = { title = "Your First Riding Ram", description = "Ah, it's a big day fer ya I see; here for yer first ram are ye?\n\nThese rams are the most steadfast and sturdy in all of Azeroth. They're fiercely protective of their rider. Aye, you'll have a hard time finding a more stalwart companion for yer journeys.\n\nSo, you have an important choice to make. You and yer ram will traverse the world together so choose wisely! Not to worry lad, whatever choice you make will be the right one.\n\nGo see the rams and return to me when you've made yer choice.", objectives = "Inspect the riding rams to choose your first mount." }
WordHunterWoW_QuestEN[97018] = { title = "Learning to Ride", description = "Hello, {class}! It would seem yer now seasoned enough as an adventurer for me ta teach ye how to ride a ram, for a fee o'course.\n\nVeron will provide ye with a free mount once ye have trained with me, and after you'll be able to purchase any additional mounts ye would like. There are many creatures out in the world, and each requires their own riding skill, but ye will have to find trainers for each.\n\nSpeak ta me when you have enough coin, and I'll teach ye all I know about riding rams.", objectives = "Learn the Apprentice Riding skill from Ultham Ironhorn." }
WordHunterWoW_QuestEN[97022] = { title = "Report to Danitha", description = "Danitha Morr has ordered you to report back to Bandarion Keep to receive additional training. Please make your way back to the keep as quickly as you are able.", objectives = "Speak with Danitha Morr at Bandarion Keep." }
WordHunterWoW_QuestEN[97045] = { title = "Your First Horse", description = "Greetings! Are you here to examine our horses?\n\nThese steeds are descendants from both the historical Lordaeron stock and our own local horses. You won't find a more steadfast companion for your journeys.\n\nChoosing one may be difficult as they are all excellent and trained to be steady even when in danger. Don't forget, you and your horse will traverse the world together. I'm sure whatever choice you make will suit you best.\n\nGo examine the horses and return to me when you have made your choice.", objectives = "Inspect the riding horses to choose your first mount." }
WordHunterWoW_QuestEN[97046] = { title = "Your First Mechanostrider", description = "Salutations! I see today is a big day indeed; today you will synchronize your biometrics to the rider detection protocol of your first mechanostrider! This protocol will help the strider distinguish you from other possible riders.\n\nAs such, you have an important choice to make. You and your strider will traverse the world together so choose wisely! Fear not, whatever choice you make will be the correct one.\n\nGo examine the mechanostriders and return to me when you have made your choice.", objectives = "Inspect the riding mechanostriders to choose your first mount." }
WordHunterWoW_QuestEN[97047] = { title = "The Cook in the Cage", description = "Hey! You! You have to help me! I was just out exploring the jungle when, all of a sudden, I was ambushed by these maniacs! I don't know what they plan to do with me, but I've heard talk of tigers and headshrinkers, and I don't want part in either!\n\nI don't know how, but you have to get me out of here! Please! A key to this cage, a disguise to sneak out, something! Anything!", objectives = "Find a key to Wendel's cage, and a disguise for him to sneak out, within the Kurzen compound." }
WordHunterWoW_QuestEN[97048] = { title = "Returning to Port", description = "Listen, I can't repay you right now, but I'm a cook on Captain Aransas' ship. I'll be sure to put in a good word for you when I get back to Booty Bay. You should speak to the captain when you get the chance. I'm sure she'll be grateful to have me back.", objectives = "Speak to Captain Aransas in Booty Bay." }
WordHunterWoW_QuestEN[97049] = { title = "Essence of Seeping Slimes", description = "If you're headed into Shaper's Terrace, I would ask a favor of you.\n\nThere are reports of slimes that live in the pools by the colorless Achromatic Crystal. I believe their essence could be of use in my experiments, and would like you to bring me some samples for study.\n\nI will make it worth your while.", objectives = "Gather 8 Seeping Slime Essence in the Shaper's Terrace." }
WordHunterWoW_QuestEN[97065] = { title = "Tip the Scales - Keefer's Angelfish", description = "An angelfish for some tastyfish. Feels like a fair trade to me.", objectives = "" }
WordHunterWoW_QuestEN[97066] = { title = "Tip the Scales - Brownell's Blue Striped Racer", description = "", objectives = "" }
WordHunterWoW_QuestEN[97067] = { title = "Tip the Scales - Dezian Queenfish", description = "", objectives = "" }
WordHunterWoW_QuestEN[97074] = { title = "Learning to Ride", description = "Hello, {class}! It would seem you are now seasoned enough as an adventurer for me to teach you how to ride a saber, for a fee of course.\n\nLelanai will provide you with a free mount once ye have trained with me, and after you will be able to purchase any additional mounts ye would like. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough coin, and I will teach you all I know about riding sabers.", objectives = "Learn the Apprentice Riding skill from Jartsam." }
WordHunterWoW_QuestEN[97119] = { title = "Now We're Cooking", description = "In addition to seeing to the spiritual needs of the people here, I feed them as well. I'm not exactly a trained cook, but after five years, I've learned a thing or two about preparing food!\n\nI'm sure that folks here would love a taste of something different. I remember, before we assembled on the mountain, there was a goblin from Everlook who was serving platters of tiny, Savory Stag Sliders... I would love to taste one of those again. We have plenty of stags up here, too! Think you can cook some up?", objectives = "Bring 6 Savory Stag Sliders to Ortak Lomgok in Elderwild." }
WordHunterWoW_QuestEN[97130] = { title = "Ancient Gurubashi Secrets", description = "Lan'dalock and I have been discussing a recent development in the south seas involving an ancient Gurubashi ruin that has suddenly appeared off the coast of Stranglethorn Vale.\n\nSuch a site has significant archeological value. We'd be highly interested in obtaining one of the idols that certain witch doctors amongst the ancient Gurubashi would use as a ritual focus for their blood magic.\n\nEnter this \"Drowned City\" and recover one of these idols for us.", objectives = "Recover an Ancient Gurubashi Idol from the Drowned City." }
WordHunterWoW_QuestEN[97168] = { title = "Material Assistance", description = "{name}, the spirits weigh heavy, both materially and spiritually. I'm in need o' yer help. Deep within the depths of the Scholomance in Lordaeron lies the Great Ossuary, thick with shadows. I'm craftin' a device to cut that dark, but I lack the means to finish.\n\nBring me two diamonds: one Azerothian, and one Pristine Black. These are not trivial items, aye -- I just don't have the resources myself. Could ye provide me with the two diamonds?", objectives = "If you are interested in helping Eldrun Stormbreaker in Ironforge, bring him an Azerothian Diamond and a Pristine Black Diamond." }
WordHunterWoW_QuestEN[97170] = { title = "Learning to Ride", description = "Hello, {class}! It would seem you are now seasoned enough as an adventurer for me to teach you how to ride a horse, for a fee of course.\n\nKatie will provide you with a free mount once ye have trained with me, and after you will be able to purchase any additional mounts you would like. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough coin, and I will teach you all I know about riding horses.", objectives = "Learn the Apprentice Riding skill from Randal Hunter." }
WordHunterWoW_QuestEN[97171] = { title = "Your First Horse", description = "Greetings! Are you here to examine our horses?\n\nThese steeds are descendants from both the historical Lordaeron stock and our own local horses. You won't find a more steadfast companion for your journeys.\n\nChoosing one may be difficult as they are all excellent and trained to be steady even when in danger. Don't forget, you and your horse will traverse the world together. I'm sure whatever choice you make will suit you best.\n\nGo examine the horses and return to me when you have made your choice.", objectives = "Inspect the riding horses to choose your first mount." }
WordHunterWoW_QuestEN[97173] = { title = "Blackmaw Magic", description = "The Blackmaw furbolgs in the mountains overlooking Azshara have been dabbling in dark magic. While a primitive people being corrupted by demonic magic is nothing new for Azeroth, Lan'dalock and I would like to study their spell foci.\n\nTravel to the stronghold known as Blackmaw Hold and recover one of the Blackmaw Ritual Totems for us. Only the most powerful of the Blackmaw's shamans will be carrying one of these, so bring allies and take care.", objectives = "Recover a Blackmaw Ritual Totem from Blackmaw Hold." }
WordHunterWoW_QuestEN[97174] = { title = "A Worthy Endeavor", description = "The time has come, {name}. As in life, paladins of the Forsaken are not complete until they are able to form a bond with a charger. This is no ordinary steed, this is a powerful spirit of retribution. \n\nSpeak with Danitha Morr at Bandarion Keep to learn more. She will guide you on what to do next. The road before you will be difficult, but as our orc allies like to say--blood and thunder <brother/sister>!", objectives = "Speak with Danitha Morr at Bandarion Keep in Tirisfal Glades." }
WordHunterWoW_QuestEN[97175] = { title = "Due Sacrifice", description = "No worthy endeavor is completed without some sacrifice, and this first task requires just that.\n\nYou must acquire High Priest Zayus's exorcism censer for your task. Even though its use will be for good reason, due compensation must be given for it.\n\nProceed to Orgrimmar and speak with the High Priest Zayus there. Zayus will seek a...\"donation\" for the loss of his censer. It will be a small price to pay when all is said and done.", objectives = "Travel to Orgrimmar and get High Priest Zayus's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it." }
WordHunterWoW_QuestEN[97176] = { title = "Exorcising Terrordale", description = "I have added some dirt from the tainted ground of Terrordale in the Eastern Plaguelands to the censer. Go there and use this censer to find areas with the greatest signs of corruption. You'll know these areas by the green necrotic auras that rise up from the ground at the location where tormented souls congregate.\n\nUse the censer to reveal these spirits. Free them from their torment. When you have put these souls to rest, return and we will discuss the next steps.", objectives = "Use the Exorcism Censer to drive out the tormented spirits in Terrordale. When you have destroyed 25 Terrordale Spirits, return to Danitha Morr at Bandarion Keep in Tirisfal Glades." }
WordHunterWoW_QuestEN[97177] = { title = "Acts of Mercy", description = "With the blessings of the loa, take the censer. I be usin' it more than once to exorcise bad voodoo spirits, and it should serve ya well for the trials what be comin'.\n\nYou best be headin' back to Danitha now, {name}. Ya quest continues with her.", objectives = "Return the Exorcism Censer to Danitha Morr at Bandarion Keep in Tirisfal Glades." }
WordHunterWoW_QuestEN[97178] = { title = "Ott of Tarren Mill", description = "A paladin's charger needs a proper barding or it is little more than a mindless beast. The barding used by your charger not only needs to be of the finest materials possible, but must also be suitable for attunement to the spirit realm.\n\nThere is a smith outside of Tarren Mill that has done great work for our paladins in the past. He is a modest and unassuming orc, but his work is superb and is well-suited to our needs. Seek him out and commission him for this task.", objectives = "Speak with Ott at the village of Tarren Mill in the Hillsbrad Foothills." }
WordHunterWoW_QuestEN[97179] = { title = "Collection of Goods", description = "We require several things for the barding--runecloth for the lining, arcanite bars for the plating, Arthas' Tears for the spiritual attunement, and Stratholme holy water for the spiritual imbuement. Lastly, I'd charge a modest fee for the labor and for the saddle and stirrups to go with the barding.\n\nBring me these materials, and I will be able to complete your barding. I'll get to work on the saddle while you work on gathering these items.", objectives = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Ott in Hillsbrad Foothills." }
WordHunterWoW_QuestEN[97180] = { title = "Ott's Finest Work", description = "<Ott wipes the sweat from his brow and grunts at his work approvingly.>\n\nThere you are. My trade is mostly in the creation of weapons, but I believe that this might be some of my finest work nonetheless. I thank you for the trust you and your fellow paladins have shown me.\n\nNo doubt Danitha Morr will want to see the work for herself as well. Take your barding to her, and give her my thanks for allowing me to complete this commission on your behalf.\n\nLok-tar, {class}.", objectives = "Take the Arcanite Barding to Danitha Morr at Bandarion Keep for inspection." }
WordHunterWoW_QuestEN[97182] = { title = "An Offering of Vengeance", description = "A paladin charger's barding requires the blessing of a powerful equine spirit. In the ruins of Dire Maul the corrupted treant known as Tendris Warpwood has such a spirit imprisoned. Seek retribution on behalf of this spirit, and free it from its bondage. With luck, it may be willing to provide its blessing. \n\nTo help ensure success, I'd also advise you to bring a special type of spiritually-attuned feed. Travel to Eastern Plaguelands and speak with the ranger known as Nathanos Blightcaller about this.", objectives = "Acquire special horse feed used for feeding a spirit horse. Nathanos Blightcaller in Eastern Plaguelands may be able to provide such a feed.\n\nTravel to the Dire Maul in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed to soothe it. \n\nLastly, give it the Arcanite Barding and hope that it is willing to provide the needed blessing." }
WordHunterWoW_QuestEN[97183] = { title = "Blessed Arcanite Barding", description = "As the barding rests on the back of the Ancient Equine Spirit, it glows white hot. The air is thick with power for a brief moment, and then the barding disappears from the back of the horse and is now secure in your backpack.\n\nEven through the leather of your satchel, you feel the heat still coming off of the saddle. It would seem that your offering of vengeance has been accepted, and the barding has been blessed. It's time to return to Danitha Morr at Bandarion Keep.", objectives = "Return with the Blessed Arcanite Barding to Danitha Morr at Bandarion Keep in Tirisfal Glades." }
WordHunterWoW_QuestEN[97185] = { title = "Justice and Retribution", description = "In this satchel you will find the items you will need for your trial. Use the divination scryer in the heart of the Great Ossuary's basement to bring forth accursed spirits to face justice. The power of your judgements will be extremely valuable in this battle, so use them wisely.\n\nOnce you have dispersed these spirits, Darkreaver will appear. Defeat him and claim the lost soul of the charger. Show it the path of justice and retribution that you walk and with luck, it will take its place at your side.", objectives = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Spirit of Retribution and the Blessed Enchanted Barding to Darkreaver's Fallen Charger." }
WordHunterWoW_QuestEN[97186] = { title = "Manna-Enriched Horse Feed", description = "So you need feed to give to the incorporeal spirit of a horse? Interesting.\n\nYes, I suppose I can help you with what you need. I have spent a considerable amount of time rearing beasts that are... let's say--no longer entirely of this world, and I know a thing or two about how to sustain them.\n\nI simply need some of the spiritually-enriched biscuits that the Argent Dawn sells... and a small offering of gold. For my time, of course.", objectives = "Retrieve 20 Enriched Manna Biscuits for Nathanos Blightcaller in Eastern Plaguelands. The Argent Dawn is known as the sole purveyor of the biscuits. You'll also need to provide Blightcaller with 50 gold for his time." }
WordHunterWoW_QuestEN[97188] = { title = "Learning to Ride", description = "Greetings, {class}! You are now seasoned enough as an adventurer for me to teach you how to pilot a mechanostrider, for a fee of course.\n\nMilli will provide you with a free mount once you have trained with me, and after you will be able to purchase any additional mounts you would like. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough gold, and I will teach you about riding mechanostriders!", objectives = "Learn the Apprentice Riding skill from Binjy Featherwhistle." }
WordHunterWoW_QuestEN[97194] = { title = "Learning to Ride", description = "Mok'ra, {class}. You are now seasoned enough as an adventurer for me to teach you how to ride one of our wolves, for a fee of course.\n\nOgunaro will provide you with a free mount once you have trained with me, and after you will be able to purchase any additional mounts you would like. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough gold, and I will teach you about wolf riding.", objectives = "Learn the Apprentice Riding skill from Kildar." }
WordHunterWoW_QuestEN[97196] = { title = "The Coldbringer's Eye", description = "There is a servant of the Lich King that makes his home deep in the Death's Head quilboar lair known as Razorfen Downs. It is known to us that he makes use of a scrying orb to observe and direct the movements of his minions elsewhere.\n\nWith this artifact, we'd be able to hunt down the covert agents of the Scourge and put an end to them and the threat they pose to Kalimdor forever.\n\nGo into Razorfen Downs to the lair of Amnennar the Coldbringer and retrieve the orb known as the Coldbringer's Eye for me.", objectives = "Recover The Coldbringer's Eye from Razorfen Downs." }
WordHunterWoW_QuestEN[97197] = { title = "Fragment of the Firelands", description = "Muln tells me that there is a location in the deepest depths of a place called Blackrock Mountain where the barrier between Azeroth and the elemental plane has been damaged, allowing a myriad of elemental creatures from the realm of the Firelands to escape into this reality, including giants as large as an Anchor Pylon!\n\nI'd very much like to study any fragments of material that could be gathered from one of these creatures. Would you brave the Blackrock Depths and recover a sample for me?", objectives = "Recover a Fragment of the Firelands from Blackrock Depths for Alaana Stormwalker in Mulgore." }
WordHunterWoW_QuestEN[97198] = { title = "Blackmaw Magic", description = "The Blackmaw furbolgs in the mountains overlooking Azshara have been corrupted by dark and sinister magic. We do not know the full extent of the corruption and what impact it may have upon the elements in the area, but we hope to understand it better.\n\nTravel to the stronghold known as Blackmaw Hold and recover one of the Blackmaw Ritual Totems for us. Only the most powerful of the Blackmaw's shamans will be carrying one of these, so bring allies and prepare for a difficult battle.", objectives = "Recover a Blackmaw Ritual Totem from Blackmaw Hold." }
WordHunterWoW_QuestEN[97200] = { title = "Learning to Ride", description = "Ey, welcome {class}! Ya now be seasoned enough as an adventurer for me to teach you how to ride one of our raptors, for a fee of course.\n\nZjolnir will provide ya with a free mount once you have trained with me, and after you will be able to purchase any additional mounts ya would like. There are many creatures out in the world, and each requires their own riding skill, but ya will have to find trainers for each.\n\nSpeak to me when ya have enough gold, and I will teach ya about raptor riding.", objectives = "Learn the Apprentice Riding skill from Xar'ti." }
WordHunterWoW_QuestEN[97203] = { title = "Learning to Ride", description = "Greetings, {class}. It would seem you are now seasoned enough as an adventurer for me to teach you how to ride a skeletal steed, for a fee.\n\nZachariah will provide you with a free mount once you have trained with me, and after you will be able to purchase any additional mounts you desire. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough coin, and I will teach you about skeletal horses.", objectives = "Learn the Apprentice Riding skill from Velma Warnam." }
WordHunterWoW_QuestEN[97204] = { title = "Learning to Ride", description = "Greetings, {class}. It would seem you are now seasoned enough as an adventurer for me to teach you how to ride a kodo, for a fee of course.\n\nHarb will provide you with a free mount once ye have trained with me, and after you will be able to purchase any additional mounts you would like. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough coin, and I will teach you about riding the noble kodo.", objectives = "Learn the Apprentice Riding skill from Kar Stormsinger." }
WordHunterWoW_QuestEN[97205] = { title = "Learning to Ride", description = "Hello, {class}! It would seem you are now seasoned enough as an adventurer for me to teach you how to ride a galestrider, for a fee of course.\n\nI will provide you with a free mount once ye have trained with me, and after you will be able to purchase any additional mounts you would like. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough coin, and I will teach you about riding galestriders.", objectives = "Learn the Apprentice Riding skill from Genn Fairweather." }
WordHunterWoW_QuestEN[97220] = { title = "Philmor's Favor", description = "Every day this week we've been short dockhands.\n\nCare to ease the stress on our cargo schedule?\n\nTake this package to the stockroom entrance of the Gatehouse. You'll find it inside Trias' Cheese shop on the second floor. The mistress, Elaine, will be quite familiar with the deliveries. The Gatehouse often has shipments arriving with more discretion to allow for ceremonial surprises on behalf of the guard's officers.", objectives = "Bring the Gatehouse Shipment to the stockroom entrance located in Trias' Cheese shop in the Trade District.", progress = "You looking to fill a crate with our finest aged wheels?", completion = "Oh, dear. You think we want to carry that up the stairs ourselves? Keeping the valuables intact is your responsibility up until the point you drop it off." }
WordHunterWoW_QuestEN[97222] = { title = "Gatehouse Goods", description = "Yes, it's only a flight of stairs, but if it's such a small ask, it should be no problem for you to finish the delivery yourself! \n\nTrias' Cheese isn't part of the Gatehouse or their stocking inventory, but our buildings share a floor.\n\nPlace the crate outside their stockroom door--the guard will send someone for a regular pickup. They will see the package arrival and carry it inside as they return to post.", objectives = "Carry the Gatehouse Shipment up the stairs in Trias' shop and leave it outside the door.", completion = "Yep. There's a reason that hinge opens inwards towards them, so they don't get the door blocked by people leaving stuff anywhere they please.\n\nConsider us professionally acquainted, {class}. \n\nWe respect your business, and expect you to respect ours." }
WordHunterWoW_QuestEN[97223] = { title = "Bloodtalon Matriarch", description = "All of the raptors you see before you are ones I have trained myself. They come from all over Kalimdor, but some of the finest come from the Bloodtalon raptors on the isles off our coast.\n\nOne raptor amongst them, the Bloodtalon Matriarch, is particularly savage and has killed many from our village and has become too dangerous to leave at our borders. If you can strike her down, return with her eggs so that we can raise the hatchlings as allies instead of enemies.", objectives = "Bring Eggs of the Bloodtalon Matriarch to Xar'Ti in Sen'jin Village.", progress = "The Bloodtalon are known for their cunning and swiftness, and make fine companions when raised from egg to adult.\n\nUnfortunately adult raptors are very difficult to train, and I have tried to capture the Matriarch on more than one occasion. But she had become too dangerous of late.\n\nStill I hope to preserve her legacy by raising her children as companions here in Sen'Jin.", completion = "Thank you, {name}. I am happy we will be able to preserve her bloodline and raise them to be our allies. You have done a great service for our tribe." }
WordHunterWoW_QuestEN[97225] = { title = "Forgotten Loa Idols", description = "When we fled the isles that Zalazane and his ilk now inhabit, we left behind many precious idols that help us commune with spirits we worship: our loa. They are of grave importance to our tribe.\n\nThe followers of Zalazane show no reverence for our loa and have scattered these idols across the largest of the isles.\n\nThis is an action that will not go unnoticed if we are not able to collect these idols, and offending a loa is a grave matter.\n\nGo, find as many loa idols as you can and return them to me.", objectives = "Collect 8 Forgotten Loa Idols from the Echo Isles. Bring them to Master Gadrin in Sen'jin Village.", progress = "Have you found our loa idols, {name}? We must begin our rituals again soon.", completion = "You have done a great deed for our tribe today.\n\nUnlike some tribes, our kinship with our loa is one of reverence and respect, and we owe them much.\n\nI would not want the Darkspear to fall out of favor with them." }
WordHunterWoW_QuestEN[97234] = { title = "Reading Room", description = "Are you here to discuss the deeper meanings of our storied legends? No?\n\nWell, after you're done looking around, can you carry this to the library for me? We're exchanging some of our less popular bodies of work for some more modern writing. I have a list of tomes I'm quite sure the librarian will be able to procure for us within our existing arrangement.\n\nComplimentary club refreshments on us, if you help us out.", objectives = "Bring the wrapped reading material to the Stormwind library.", progress = "Please keep your voice down.", completion = "Let's see here. Roy's Book Club, isn't it? I recognize this wrap technique. \n\nWell, if he says this is what people want to talk about, it's all fine by me. The material we receive back is always in as good of quality as we loaned it, so we know they're treating it with respect regardless of how provoking the words may be." }
WordHunterWoW_QuestEN[97236] = { title = "Fang of Githyiss", description = "A fresh specimen from a beast of this size is quite a find. Perhaps someone in Aldrassil familiar with the study of spiders would be interested in the fang.", objectives = "Deliver the Fang of Githyiss to someone interested in the study of spiders in Aldrassil.", completion = "My, my. How I do love surprises, {name}.\n\nThis specimen will surely help further my studies." }
WordHunterWoW_QuestEN[97237] = { title = "Shelf Picked", description = "I've checked our inventory and all of the selections Mr. Lewells has listed are currently available.\n\nYou will, however, need to procure them off the shelves yourself. Part of our librarian duty is vigilance, and for that, I will resume supervisory bookkeeping.\n\nReturning with the material to Roy on his behalf will not mark yourself accountable for their return; as with his note you're serving as the book club's official courier. Their establishment shall carry that burden.\n\nGood day, {name}.", objectives = "Find each of the reading materials located somewhere in the library and then return to Roy Lewells in Stormwind's Park.", progress = "You forgot what you had to do the moment you stepped through the door, eh? Happens to everyone.", completion = "These are them! Some of them even smell exotic! Fantastic, I can't wait for us to have lively conversations about these writings.\n\nCellar after hours, of course.\n\nThanks for the quick errand run, {name}. As promised, it's on the house. We keep our word here." }
WordHunterWoW_QuestEN[97242] = { title = "Yelmak's Medley", description = "Yelmak doesn't want his apprentice breaking anything. Well, anything more than he already has.\n\nHe told me the young mixer in training has too much pride to ask for help when he really needs it. Yelmak wants to give him a taste of a particular home-brewed recipe.\n\nGather a mix of cattail and speargrass cuttings taken from the plants growing around the water in the Valley of Honor. I'd get them myself, but if I left the shop, Whuut would surely know we're catering to his mood.", objectives = "Take some cuttings from the Cattails and Speargrass growing around the water flows in the Valley of Honor and return to Kor'geld in Yelmak's Alchemy and Potions.", progress = "We discover formulations and recipes by showing old ingredients to new generations, who experiment with them in their own way.", completion = "This type of cattail and speargrass is unique to Orgrimmar. Drinking from Azshara mountain spring water, and nourished by the sweat and blood soaked mineral dust of our rocky land, these herbs contain potent powers locked within.\n\nI'll give these to Yelmak, who may be able to win back Whuut's ear with a hands-on lesson." }
WordHunterWoW_QuestEN[97243] = { title = "Call of Fire", description = "Even though we are in the realm of Skywall, this is still the elemental plane. The spirits of all four elements speak to us, if we deign to listen. One among us Windshapers is in particular attunement with the element of fire. A shen'dorei by the name of Olariaan Swiftburn.\n\nBring this to him at the Shrine of Flames in the Gustberry Lowlands. You'll find it tucked away along the edge of the island, west of Valanaar.", objectives = "Bring the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames in the Gustberry Lowlands.", progress = "Yes, {name}? What do you have there?", completion = "So you've brought the torch. Yes, young {class}, I can teach you to heed the call of fire. It will not be easy, but nothing that we do in this realm is ever easy." }
WordHunterWoW_QuestEN[97244] = { title = "Call of Fire", description = "There is an Al'Aketh Skypriest called Faladiel. He was once a caller of the flame and a stalwart Windshaper. Like so many Al'Aketh, he mortgaged his loyalty for power and his hands are now stained with the blood of his former brothers and sisters.\n\nYou will find Skypriest Faladiel at the farm to the northeast past Valanaar, just to the south of the Shrine of Akir. Kill the betrayer. Bring me his heart. It is a gruesome task, but it is needed for the ritual we are to perform.", objectives = "Slay Skypriest Faladiel in the Gustberry Lowlands and collect Faladiel's Heart.", progress = "The heart of a betrayer is a powerful reagent. The flames will eagerly accept such an offering and burn more intensely as it is consumed.", completion = "The Windshapers do not forget, and blood is always paid with blood. It pleases me that you were able to deliver this final, painful reminder of our creed to this traitor.\n\nThis heart will not be all that feeds the flames today, however. There is one other task that needs to done." }
WordHunterWoW_QuestEN[97245] = { title = "Call of Fire", description = "The residents of the Shen'dar Highlands speak of an ancient forest sprite called Kuramaa. They say it lives inside of a twisted stump at the summit of a hill near the highlands Anchor Pylon.\n\nGo to the highlands and find this stump. Rap your fist upon the bark and Kuramaa will appear. Best the spirit in combat, and bring me its wooden mask.\n\nBe warned however, this entity will be exceptionally resistant to much of your magic. Only the touch of flame will lay low the spirit.", objectives = "Find the home of Kuramaa in the Shen'dar Highlands, and defeat the spirit in combat. Bring Kuramaa's Mask to Olariaan Swiftburn in the Gustberry Lowlands when you are victorious.", progress = "The spirit of Kuramaa is eternal, and it will manifest again when it is needed. It's mask is a source of great power, and will prove invaluable to the ritual we must complete.", completion = "We now have what we need. We will light the eternal flame and commune with the spirits of fire." }
WordHunterWoW_QuestEN[97246] = { title = "Meal Appeal", description = "My son, Migi, always takes off to play with his friends all day. I tell him to pick up a lunch at Borstan's, but I know he almost never does, because he comes home starving. These kids think their games are more important than their own bodies!\n\nPlease, stop at Borstan's Firepit and tell him you're there to deliver Migi's lunch. You can almost certainly find Migi behind Grommash Hold with the rest of his friends.\n\nDuties keep me here during the day and I can't watch over his every meal.", objectives = "Visit Borstan's Firepit and tell him Thatog wants you to deliver Migi's lunch to him personally.", completion = "Of course. Migi's parents and I have an arrangement to give Migi a bagged lunch every day, but I can only ensure the boy gets his food if he actually comes in to pick it up.\n\nSometimes, he doesn't pick up his meal multiple times a week, and I wonder where he gets the energy to stay out and play." }
WordHunterWoW_QuestEN[97249] = { title = "Favorite Food", description = "Now that I know his parents worry about how much he's actually filling that belly, I've got an idea. \n\nThey made me promise not to pack the same meal every day, so Migi grows a taste for more than one thing. Still, whenever the smoker's full and we're making sweetglazed hog belly sandwiches, he always shows up for lunch. We've started crumbling the leftover crispy glazed bits as a topping--something we can add daily. \n\nTake this to him. Maybe he'll start showing up early and bringing friends!", objectives = "Bring Migi's Lunch to him behind Grommash Hold.", progress = "I think we can win this one...", completion = "Borstan's Meats? Is that for one of us?\n\nOh!\n\nWow... this smells really good! Yummy.\n\nThanks for bringing me my lunch. I can tell what Borstan is going to be serving daily when my friends and I walk the road to Grommash Hold, by the smells alone. This tastes like my favorite, the sweetglaze! But it's different. I like the strong-flavored crumbs.\n\nIf it's going to be this tasty every day, I think we need to stop our game to take our lunch together!" }
WordHunterWoW_QuestEN[97250] = { title = "Wrongly Blamed, Justly Corrected", description = "Traveler, have you plans to head toward Dustwallow Marsh? I have heard mutterings that a few human soldiers have taken a stand at its border and are toppling the landmarks left behind by our tauren pathfinders.\n\nRumor has it that a favored tavern has burned to the ground, and in typical Alliance fashion, they immediately cast their blame onto the Horde! I cannot know whether there is any truth to their claim, but their incursion onto OUR land must not stand.\n\nKill first, investigate later!", objectives = "Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo.", completion = "So the rumors were true! I expected as much, tensions have been rising along the eastern coast for some time. I knew it would only be a matter of time before conflict crept into our territory.\n\nHowever, I am skeptical that we played a role in the tavern's destruction. Too many Horde civilians rely on that route for trade and travel. Perhaps you could investigate further if you find the time.\n\nIn any case, today's deed is a victory for the Horde, and a stern warning to the Alliance!" }
WordHunterWoW_QuestEN[97253] = { title = "Parts and Pieces", description = "Hey, got a sec?\n\nSo, apparently, nobody I've sent to deal with the recent pirate problem has come back alive. After five or six attempts I thought, \"what if I sent a machine instead?\" Turns out, scimitars double as screwdrivers in a pinch, and before I could redirect it home, it was already in pieces and scattered across their camp!\n\nI need those parts back, and since this is a quick little retrieval mission, I'd wager your odds for survival are MUCH higher than the others. Whaddya say?", objectives = "Collect 5 Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet.", progress = "Not another word out of you until your pockets are jingling with metal!", completion = "Whooooa! Nice one, pal! You saved me from another one of Gagsprocket's unbearable lectures on the cost of metal. More importantly, I can jump right into building my next prototype.\n\nUhhh, I didn't have a reward planned... Do you like boxes?" }
WordHunterWoW_QuestEN[97257] = { title = "Call of Fire", description = "Now we will perform the ritual. \n\nI will place the materials onto the altar and call forth the spirits of flame. If the offering is accepted, they will appear and light the Eternal Flame. You will then hold your torch forth and capture the flame.\n\nCarry the lit torch to Valanaar and place it in the Brazier of Eternal Flames. You must do so quickly, for the flames of the Firelands are quick to dissipate here in Skywall.", objectives = "Wait for Olariaan to begin the ritual at the Brazier of Offering and follow his instructions.\n\nYou must deliver the Eternal Flame to Valanaar before the timer runs out.", progress = "You have done well to come this far. You do the Windshapers honor, {name}.", completion = "It is done. The Eternal Flame burns once again.\n\nYour trial is now complete. I am pleased to present you with your Fire Totem. Use this icon of power well in your travels, {name}. \n\nJust remember, the power of the elemental plane serves those that respect it, and consumes those who do not. This is our way." }
WordHunterWoW_QuestEN[97263] = { title = "Your Package Has Arrived", description = "<Several misplaced packages have been left by the mailbox. You note that one of them is marked for delivery from Aerie Peak, to Ironforge, to Eldrun Stormbreaker. It is marked \"urgent.\">", objectives = "Deliver Eldrun's misplaced package.", progress = "What's that you've got there?", completion = "What! I've been going to the mailbox by the bank every day looking for this package! This city needs to figure out its layout. Not easy to navigate like Aerie Peak!\n\nLet's see what I've got... totem carving tools... spare axe... some kind of goblin device? I didn't order that! Ah, I'll just send it back.\n\nEr, uh... I mean... thank you for bringing all of this to me. Here's a little something for your trouble." }
WordHunterWoW_QuestEN[97264] = { title = "Shardtooth Pulling", description = "The Shardtooth are becoming more rabid every season. They compete with each other and the predators of the wilds for what limited food sources they can reach.\n\nMore often, they attack us, hunger driving their aggression in the bitter cold.\n\nThe bears are numerous and strong-willed. With their numbers reduced, the families that remain will grow stronger than ever.\n\nHelp them on their way. Cull the eldest of them.", objectives = "Remove 12 Elder Shardtooth from nearby areas, then return to Sarna Brownhorn." }
WordHunterWoW_QuestEN[97265] = { title = "Hate the Hatefury", description = "Ever strike a deal with a satyr, mon?\n\nI have. How could I resist? The promise of power, knowledge far exceeding what any ordinary tome could offer... all alongside an eager and charismatic minion. What more could I ask for?\n\nBah, of course they would never bend the knee to a mortal. I bargained when I had nothing, only to be cast aside with even less.\n\nNow, I want revenge. Revenge against the Hatefury. Raid their camp to the northeast! Stain the dirt with their foul blood.", objectives = "Defeat a variety of Hatefury satyr at Sargeron in Desolace and then return to Aka'rai in Shadowprey Village.", completion = "I wish I had been able to watch your battles unfold and hear their wretched screams as they fell to your might.\n\nBut one of them surely eluded your slaughter. The one whose hand I shook in a ritual of spilled blood. So long as he roams the Desolace, I cannot risk stepping foot outside of Shadowprey. He would soon find me again, and with my soulstone in his possession... not even death would be an escape.\n\nEventually, I will have it back. But for now, your work is done." }
WordHunterWoW_QuestEN[97270] = { title = "Brawl at the Maul", description = "There must be more to the Maul than this!\n\nPerhaps the loud Spectator who oversees the event at Dire Maul will know!", objectives = "Speak with Griniblix the Spectator above the Maul in Dire Maul." }
WordHunterWoW_QuestEN[97275] = { title = "Whuut's the Rush", description = "Whuut is a prodigy. That much is true. But he doesn't yet have the experience, wisdom, and time on the stirring rod to know how to respect alchemical processes.\n\nHe is exhausting all of the rarest and most exotic reagents we have available without pausing to practice and refine his basic skills.\n\nGive him this potion I've brewed with a quick tonic method. He'll reconsider everything he's doing when he learns how local remedies and careful touch are the first true mastery.", objectives = "Give Yelmak's Potion to Whuut.", progress = "Alright, what's next... Black Lotus, Mountain Silversage...", completion = "Grorru--whaa?\n\nYou say Yelmak made this potion from speargrass and cattail with no other reagents? I didn't know chemists had any real need for these common plants we see every day.\n\nMaybe he's right. There could be a lot I'm missing out on by skipping to the most rare and least-studied flora first.\n\n{name}, take your pick from one of these potions I brewed earlier. I appreciate you taking the time to visit our shop." }
WordHunterWoW_QuestEN[97277] = { title = "Grund and Gozwin", description = "Oi, had me back turned gettin' the boar roast ready when I heard me pal Gozwin screamin' fer his life!\n\nWicked fangs and a blur are all I saw when I turned. Such huge paws! A snow leopard was draggin' its gnomish catch away. I grabbed me shotgun and fired above the beast. It dropped him and sprinted off.\n\nLuckily, it hadn't done more than give ol' Goz some deep scratches.\n\nHead back to camp in the northwestern hills and retrieve Gozwin's Mechanic's Log. Kill that snow leopard too if you see it!", objectives = "Find Grund and Gozwin's camp in the hills to the northwest. Recover Gozwin's Mechanic's Log and kill the Snow Leopard Prowler.", progress = "Poor Goz is more concerned for his mecha-walker than himself. Says if anyone gets a hold of that mechanic's log he's greased. Hah! That's why I told him he should just leave his work at home!", completion = "Aye, I'm not surprised to hear that snow leopard was makin' a meal of the boar we were fixin' fer roastin'!\n\nGoz will have one less thing to stress about now that you brought back his log book. Maybe now he can focus all his energy on gettin' back on his feet.\n\nThanks, {name}. Take a little something as a token of my appreciation, fer makin' the trek, and fer protectin' the hills." }
WordHunterWoW_QuestEN[97279] = { title = "Wayward Weapons", description = "With an influx of new recruits like yourself, it's been hard to keep our weapons supplied. Our weaponsmith, Kzan, is running low on training weapons and I'd like to see what kinds of skills you possess to get an idea of what I have to work with. Luckily for you, I have a solution to both.\n\nWhile you're out there cutting your teeth on boars, salvage six abandoned training weapons. Our failed recruits left them laying on the ground. Once you do, return them to our weaponsmith Kzan behind me in the Den.", objectives = "Collect 6 Abandoned Training Weapons, then return to Kzan Thornslash in the Den.", progress = "Throm'ka, {class}. Gorak told me I should be expecting you. It is good to see you in one piece!\n\nWere you able to collect the training weapons I requested?", completion = "Thank you for returning these weapons, {name}. I will get to work repairing them for the next wave of recruits." }
WordHunterWoW_QuestEN[97281] = { title = "A Simmering Storm", description = "<Before you is a strange orb with a dull surface. When picked up a small electrical current seems to vibrate from within. Upon closer inspection, it looks as if a dark mist swirls within and every so often a small electrical spark can be seen.\n\nIt is clear the harpy was using it for some purpose. Perhaps Rezlak would be interested in this object?>", objectives = "Bring the Dull Stormy Orb to Rezlak near Drygulch Ravine.", completion = "Woah, where did you find a neat thing like that? Ya know it reminds me of the other thing my boss Gazlowe always used to tell me..." }
WordHunterWoW_QuestEN[97282] = { title = "Stormy Potential", description = "\"Rezlack, when an opportunity comes knocking make sure you're ready to seize it.\" That's another gem Gazlowe taught me and that's exactly what I intend to do.\n\nThis orb doesn't seem damaged, it just looks like it's out of juice, but I've the idea to supercharge it back to full strength!\n\nThere are a bunch of thunder lizards in a gorge west of here. They have organs that hold a strong electrical charge that would be perfect for this.\n\nGo harvest some and bring them back to me!", objectives = "Bring 5 Charged Thunder Lizard Organs to Rezlak near Drygulch Ravine.", progress = "It might come as a surprise that with a name like thunder lizard they shoot lightning instead of roaring like thunder.\n\nWell, they do. Shoot lightning, I mean.\n\nTrust me, it's a lesson you only get to learn once if you're lucky.", completion = "Hey, thanks pal! You've been a really big help to me here and I appreciate it.\n\nHere's to hoping I can get this all charged up using these organs. I bet it'll make those no good harpies think twice about attacking my caravan again. I sure hope this works.\n\nEither way you've done your side of the deal. Take this for your trouble." }
WordHunterWoW_QuestEN[97284] = { title = "Vahlarriel's Vengeance", description = "If Malem is still alive, then I suspect the Burning Blade orcs are expecting someone to come searching for her soon enough. They will certainly be ready for a fight.\n\nI would prefer if you kept a low profile and stayed out of their way, but the far more likely reality is that they will be looking to meet you, blade to Burning Blade, at every opportunity.\n\nSo how about we plan to keep score from the start. Kill as many as you can, and I'll make it worth your time.", objectives = "Slay Burning Blade orcs at Thunder Axe Fortress in the Desolace, then return to Vahlarriel Demonslayer at Nijel's Point." }
WordHunterWoW_QuestEN[97286] = { title = "Research Access", description = "", objectives = "Your actions show you are one who respects knowledge. The library is open for use in your studies.", completion = "Your actions show you are one who respects knowledge. The library is open for use in your studies." }
WordHunterWoW_QuestEN[97287] = { title = "Shrewd Negotiations", description = "You have done well to infiltrate the city of mages, but I believe it is time for us to be more... negotiatory.\n\nAs much as it pains me to admit, there is no other place on Azeroth with such a vast knowledge of the arcane. My brilliant work still pales in comparison to the ancient wisdom the Kirin Tor have amassed over the years. I think it's high time we are granted access to this exclusive order, don't you think?\n\nTake the mote you acquired. They will surely give anything to get it back. Anything.", objectives = "Speak with the Image of Archmage Modera near Dalaran.", progress = "Oh, you are back.", completion = "You would give this... willingly?\n\nI do not know your game, {race}, but I cannot deny the value of your interference during this delicate time for our people. It's not within my power to grant you access to the city at this time, but someday... perhaps. For now, our thanks will have to suffice." }
WordHunterWoW_QuestEN[97288] = { title = "Unending Torment", description = "<As the creature falls, its head comes toppling off. It seems as if it has been reattached several times, and the connection gets weaker with each reconnection.\n\nSomeone in the Undercity would know more about this unique abomination.>", objectives = "Deliver the Abominable Head to Master Apothecary Faranell within the Undercity.", progress = "What have we here?", completion = "Oho! I believe I know this head. A cruel joke by our Dark Lady. A delicious one at that.\n\nI think I have a use for this." }
WordHunterWoW_QuestEN[97289] = { title = "Unending Torment", description = "We craft abomination heads all the time, but this one is special. It belonged to a Grand Marshal of the Alliance once. A particularly unpleasant one. Othmar, I believe its name was. The Dark Lady had the pleasure of dispatching this one herself.\n\nOoh the secrets it could tell if it could talk. And it can! If we reattach it to an appropriate host.\n\nGo ahead and place it next to the available body in the next room. But don't attach it. Not yet.", objectives = "Bring the Head of the Baron to the body of Othmar in the Undercity.", progress = "<The abomination remains lifeless without a head to control it.>", completion = "<The body twitches to life, panicking as it relives its final moments.>\n\nYou..." }
WordHunterWoW_QuestEN[97290] = { title = "Unending Torment", description = "You... abomination...\n\nWhy should... help you...\n\nBe gone...", objectives = "Report your findings to Master Apothecary Faranell in Undercity.", completion = "Not cooperating, eh? Excellent. I always love a challenge." }
WordHunterWoW_QuestEN[97291] = { title = "Unending Torment", description = "With the head reattached, all we need now is to bind it to the Dark Lady's will. This should not be a problem. The beast barely has brains left as it is after all the beatings it's taken.\n\nWe simply need to motivate it.\n\nFetch me a Toxic Skullcap from Miss Grisette in the Trade Quarter. Oh, and some Blisterweed from our local herbalist trainers, the Alliestars. Feel free to just take some, they owe me. And lastly a bit of Essence of Agony. Any old poison vendor should do.\n\nWe have a potion to make!", objectives = "Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity.", progress = "It will be ever so lovely to have our lost sheep returned to the fold, don't you think?", completion = "These will do nicely. We will see how much bravado our honored guest retains after he is subjected to my masterpiece." }
WordHunterWoW_QuestEN[97292] = { title = "Unending Torment", description = "I have concocted a lovely serum that our new guest is sure to find quite... stimulating.\n\nTake this. Feed it into the workings dripping from above him. Let's see if we can't show him why it's in his best interest to serve loyally.\n\nAnd try not to drop it. I can't afford a new assistant.", objectives = "Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell.", progress = "For Othmar's crimes against the Dark Lady, placing him under that oozing specimen is the least he deserves.\n\nAnd it's funny...", completion = "Excellent. We'll let his flesh simmer for awhile. Give him time to acclimate to his new home.\n\nI have no further use for the wretch for now, but we shall keep an eye on him. I have many plans for Othmar's future." }
WordHunterWoW_QuestEN[97319] = { title = "A Cousin Abroad", description = "A cousin of mine on Kalimdor has been cutting his way through the most dangerous sites there and, last I heard, is on his way to Mount Hyjal.\n\nThis seems like a ridiculous waste of time.\n\nIf you ever find yourself out in that part of the world, it would be good to know that he hasn't gotten himself killed. Yet.", objectives = "Find the missing cousin somewhere on Mount Hyjal." }
WordHunterWoW_QuestEN[97326] = { title = "Rocks to Rests", description = "Hey! You've got time to help us out! I know you do, I can tell by the way you smiled watching the game we're playing.\n\nThis spot behind Grommash Hold is nice because it's clear enough for us to set up our figures. But what stinks is we don't have enough rocks for chairs or tables.\n\nYou're big and strong... d'ya think you could carry back some medium-sized rocks, smooth enough to sit on if we need a rest?", objectives = "Return 8 Smooth Boulders to Thra behind Grommash Hold.", progress = "It's nice to not have to always sit in the dirt!", completion = "How can you even hold all of those boulders!\n\nThose are great. Most even have a nice flat side, too. Now that you carried them all the way over here we can scoot them around in the dirt, right where we want 'em.\n\nThanks, {name}!" }
WordHunterWoW_QuestEN[97327] = { title = "Blackmaw Pouches", description = "It breaks my heart to admit, but my brothers and sisters inside Blackmaw Hold are irreparably corrupted.\n\nIf you bring me some of their personal belongings, I can at least give their families something to remember them by. Every bundle you recover will serve as a symbol of your service to my people.", objectives = "Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara." }
WordHunterWoW_QuestEN[97328] = { title = "Anything of Value", description = "<As you sift through the debris left behind by a horrible zeppelin crash directly above, you find evidence of a hefty shipment of supplies that has long since been plundered of all its value. Even the shipping labels have been torn and shredded, leaving only the words 'Booty Bay' barely legible on one.\n\nCountless two-toed footprints and several patches of divotted earth all lead toward ruins in the northwest.>", objectives = "Recover 8 Stolen Shipments from the Ruins of Zul'Kunda in Stranglethorn Vale and return your haul to someone in Booty Bay." }
WordHunterWoW_QuestEN[97329] = { title = "Where's the Key?", description = "You! Yes, you! Come here, keep your voice down!\n\nI screwed up big time. I managed to secure a sweet deal for Booty Bay to use their zeppelin tower for expedited deliveries and on our very first route I saw a huge bird--err, got SHOT DOWN just to the east of here!\n\nI survived the crash, unfortunately, but before I woke up, I was already being dragged by my ears! Now I'm surrounded by bloodthirsty trolls and locked in a cage!\n\nLook, I just need the key, okay? I can escape on my own.", objectives = "Bring the Primitive Key obtained from the trolls at the Ruins of Zul'kunda in Stranglethorn Vale to Zimmix Sputterspark." }
WordHunterWoW_QuestEN[97331] = { title = "Zimmix's Great Escape", description = "Wait, wait, don't go yet!\n\nI know I said I just needed the key but... well, they caught me once, they could do it again, right? I'm just one goblin, and there's hundreds of trolls around here!\n\nYou've already put enough of a dent in their numbers to get this key, so it should be easy enough to stand guard while we mosey on out of here, huh?", objectives = "Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue." }
WordHunterWoW_QuestEN[97332] = { title = "Twice Misplaced Trust", description = "As much as I don't like the guy, I've heard what the Bloodscalp tribe do to their prisoners, and it ain't pretty. I'm glad Zimmix made it out alright.\n\nHowever, I have another urgent delivery and I do NOT trust him to take it on. The problem? Nobody else will be available to take this before he does. You, however, have rescued lost cargo and a captured goblin, so you're looking pretty trustworthy from down here.\n\nAny chance I can convince you to take this to Whizzbuzz at Powderfuse Port?", objectives = "Deliver the Twice Reordered Package to Wharfmaster Whizzbuzz at Powderfuse Port in the Riverglades." }
WordHunterWoW_QuestEN[97378] = { title = "Mirrorscale", description = "{name}, you have proven you are a strong and dutiful hunter and I am impressed by your bravery. It is only because of this I offer you this hunt.\n\nA wind serpent hunts along a road off the coast of Feralas and has been ambushing travelers, and leaving their corpses strewn about the road. It is clear she does not hunt out of necessity. This is a creature that no longer shares the Earthmother's blessing.\n\nThe windserpent Mirrorscale makes her lair at the bottom of the waterfall along the coast of Feralas.", objectives = "Bring Mirrorscale's Wing to Melor Stonehoof in Thunder Bluff." }
WordHunterWoW_QuestEN[97386] = { title = "The Offense of Grom'gol", description = "{name}! Your arrival is timely, as always.\n\nYou have provided valuable assistance to the defense of Grom'gol, and we are grateful. After your recent push against the ogres nearby, we sent out a scout to see if there are more out there that may try to enact vengeance against us. As it turns out, there is a cave far to the east that they have claimed as their hovel.\n\nGather a friend or two and make it very clear that we will not tolerate another threat to our settlement, now or ever!", objectives = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill ogres at the Mosh'Ogg Ogre Mount." }
WordHunterWoW_QuestEN[97403] = { title = "Two-Headed Ravagers", description = "These chimaeras are a cruel joke. Two tongues, both foul, snarling frost and hunger. As if this wasteland needed more teeth.\n\nThis clearing is all we have, constantly overcome by storms before we can settle further. The two-headed Chillwind Ravagers circle us, testing our resolve, bleeding our time.\n\nWe spend more hours driving them back than building anything of worth.\n\nCull them. Break their presence here. With fewer prowling beasts, we may yet carve something lasting from this frozen waste.", objectives = "Kill 15 Chillwind Ravagers and return to Rilan Howard in northern Winterspring." }
WordHunterWoW_QuestEN[97404] = { title = "Too Bad to Bear", description = "There are two old matriarchs, long aged past their cub rearing cycles. Perhaps they are sisters. They could also be two kindred bears who've shared a similar passing of seasons.\n\nRegardless of what has brought them together, they still have a ferocity and will to live that demands respect. Attempting to set up a camp like this one has been difficult for us, with these two grizzled Shardtooths.\n\nBring back the heads of Kuroma and Kamuro, and try to end them swiftly, skillfully, and with mercy.", objectives = "Kill the old shardtooth matriarchs, Kuroma and Kamuro, and return their heads to Sarna Brownhorn." }
WordHunterWoW_QuestEN[97405] = { title = "Noise Complaints", description = "Gnaz over there has been building that death trap for the competition all the way over in Kalimdor. I have been warning him that his constant late-night tinkering is making a ton of noise, and last night I saw an ogre peeking his ugly head out from behind that tree!\n\nHe's obsessed with this ambitious dream to win the Mirage Raceway Championships, but I'm obsessed with not getting mauled to death! Please head over the hill to the north and make sure they stop snooping around the place.", objectives = "Knaz Blunderflame wants you to kill 3 Mosh'Ogg Spellcrafters, 3 Mosh'Ogg Warmongers, 3 Mosh'Ogg Maulers, and 3 Mosh'Ogg Shaman at the Mosh'Ogg Ogre Mount." }
WordHunterWoW_QuestEN[97411] = { title = "An Earnest Proposition", description = "Hail, {class}! I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", objectives = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Lightforge Bracers to Mokvar in Orgrimmar." }
WordHunterWoW_QuestEN[97420] = { title = "Reduce, Reuse, Reconcile", description = "I have a favor to ask of someone, and you look helpful!\n\nYou see this baby here? Ain't she a beaut? This is my newest racer, designed and built all by myself, because SOMEONE wouldn't help. I plan on taking this to the races in Thousand Needles, but it needs a little extra kick.\n\nNow, I'm too handsome to be a goblin, and I know better than to trust their tech, but I know the Venture Co struck liquid gold over at the lake. I'm sure they won't mind if you, erm, borrowed some? They won't even notice!", objectives = "Acquire 4 Drums of Crude Oil from the Venture Co. operations at Lake Nazferiti, then return to Knaz Blunderflame in Stranglethorn Vale." }
WordHunterWoW_QuestEN[97446] = { title = "Your First Riding Kodo", description = "Ah, I've been expecting you {class}. It would seem the winds have brought you to me this day. You have come seeking a kodo, correct?\n\nThe kodo is a noble beast that is slow to anger, and you would be hard pressed to find a more dependable companion.\n\nToday you have an important choice to make. You and your kodo will travel the world together, so find which one speaks to you. Fear not, whatever choice you make will be the right one.\n\nGo examine the kodos and return to me when you have made your choice.", objectives = "Inspect the riding kodos to choose your first mount." }
WordHunterWoW_QuestEN[97447] = { title = "An Earnest Proposition", description = "Well met, {class}. I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment. Bring me a sizeable sample of it along with the bracers and a small amount of gold. You shall find the effort worth your while.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bindings of the Elements to Deliana in Ironforge." }
WordHunterWoW_QuestEN[97453] = { title = "Weed Whacked", description = "Hi, can you help me?\n\nMy parents finally let me come along with them to this big jungle and they even let me pick a few plants just outside the gates. I'm trying to study herbalism so I can be an alchemist one day!\n\nAnyway, I almost filled my backpack when a bunch of huge, angry weeds came out of nowhere and started spitting at me!\n\nI ran away, and I'm fine, but now they won't let me play outside of the camp anymore. Can you make it safe for me, and then tell my mum?", objectives = "Slay 6 Carnivorous Weeds south of Grom'gol and then inform Gemmil's mother." }
WordHunterWoW_QuestEN[97485] = { title = "Traditions of the Bluff", description = "Blessings of An'she, friend.\n\nWe tauren have a tradition of scattering incense to the winds and I was hoping you'd be interested in honoring this tradition.\n\nYou will need to craft the incense by purchasing herbs from Nida, cedar from Nata, sinew thread from Mahu in the mid rise, and ceremonial flint and tinder from Naal on the upper rise. Once you have these items, combine them and spread them off the south facing cliff of Hunter's Rise.\n\nYou will find a mat and incense at the ceremonial site.", objectives = "Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Cedar Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\n\nCombine the items and sprinkle the incense off of Hunter's Rise.", progress = "There are many occasions one may choose to spread incense to the winds. You could be asking the Earthmother to watch over someone, bless a hunt, celebrate an occasion, or even to seek guidance from our ancestors.\n\nOr it could be something else entirely.\n\nThough the act is done with reverence, it is not strictly a ceremonial affair. Typically there are certain traditional steps observed when performing this act, but many tribes have differing practices.", completion = "You have done well.\n\nI thank you for taking the time to perform one of our time-honored traditions, {race}. I hope that as you travel you will find plenty of occasions you wish to give thanks for.\n\nShould you ever wish to perform the ritual again, you should be able to repurchase the components I sent you to collect.\n\nGo with An'she's warmth." }
WordHunterWoW_QuestEN[97490] = { title = "Halt the Hail", description = "Hey bub, I'm trying to break down some junk to get parts for my machine, but things are gettin' too hot.\n\nI know what you're thinking, Winterspring? Getting hot? As you can see, my crusher and reployer are running, but sputtering hard! What they really need is something to cool 'em down that won't melt, slide, or burn off.\n\nIn the southern hills roams a nasty giant we call Hailspite. Put an end to Hailspite and bring me the frosty moss that grows on his crags. \n\nIt might work for me!", objectives = "Search the southern hills of Winterspring for the giant known as Hailspite and recover the frost moss that grows upon him." }
WordHunterWoW_QuestEN[97530] = { title = "Dunemaul Dues", description = "A merchant caravan took a wrong turn through the desert and got jumped by the Dunemaul ogres. Only reason they made it out alive is 'cause they tossed some cargo overboard to distract the brutes.\n\nMust be this merchant's got friends with the nobs runnin' ships and zeppelins, 'cause now they want ME pickin' up what got lost.\n\nI'm stuck here working. But if YOU see a nice shiny bangle while you're beatin' on ogres, I'll make it worth ya while.", objectives = "Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to recover a particularly shiny bangle bracelet lost near the Dunemaul ogre compound." }
WordHunterWoW_QuestEN[97534] = { title = "Gritty Business", description = "Pssst, wanna know somethin'? It's easier to make profit in a place like this than you think... it's all about knowing how to market! I've seen what these tech-heads do when they get their hands on something they think they can turn into a fuel cell.\n\nEven better if it's still glowin' or sputtering steam.\n\nWhy don't we strike a deal? Bring back some of the parts that fall off their machines in the desert, and I'll kick you back a share of the coin I get from selling the salvage back to the junkers!", objectives = "Quinn wants you to recover 7  pieces of Desert Debris and return to her in Gadgetzan." }
WordHunterWoW_QuestEN[97536] = { title = "Gnomish Garbage", description = "The Matter Transporter required experimentation to get right. Many tests were conducted on all sorts of materials... with various outcomes! Some of the results are no longer with us. Others have become dangerously charged!\n\nThese subjected objects emit an energy that burns if you stay near for too long. Almost like they've been charged with a year's worth of the desert sun's power.\n\nTake this Crate of Radioactive Refuse and empty the contents in the sand a safe distance from town and other trash.", objectives = "Jhordy Lapforge wants you to return to him after you have dumped the Crate of Radioactive Refuse in the desert of Tanaris a safe distance away from Gadgetzan and other trash." }
WordHunterWoW_QuestEN[97538] = { title = "Pigments for Paints", description = "Greetings, friend. I wonder if I may ask a favor of you? I have just run out of red pigment for my paints, and I am looking for one with younger hooves to make the long journey into the Stonetalon Mountains on my behalf.\n\nIn the middle of the mountain pass there lies a large circular lake, Mirkfallon Lake, that has a unique plant that grows within its waters. The pods of this plant, mirkweed, turn a vibrant red when dried. Gather the pods of this plant for me, and I will reward you well for your efforts.", objectives = "Tah Winterhoof in Thunder Bluff wants 30 Mirkweed Pods from Mirkfallon Lake.", progress = "You have returned! Were you able to find the mirkweed plant pods in Mirkfallon Lake?\n\nWe tauren have used this plant pigment in our paints for generations, so any amount you manage to bring would be appreciated. Though there are many ways to get a red pigment, I find the mirkweed to give the richest and most vibrant hue of the methods I'm familiar with.", completion = "Ah, thank you, {name}.\n\nIt means much to me to have you venture all the way out there for what must seem a trivial notion from an old tauren, but with your kindness I will have enough pigment for the rest of the season.\n\nThank you for supporting my livelihood, and I will strive to create something magnificent with the pigments you have brought." }
WordHunterWoW_QuestEN[97539] = { title = "Silky Sutures", description = "This encampment is being left to rot. The siege damage stands, unrepaired, as if neglect were policy. I won't permit that same decay here. The infirmary answers to me, and I intend to keep it functional.\n\nWe are nearly out of supplies. I'm going to need more equipment--enough to keep the workers and guards on their feet.\n\nUnder pressure, we can make quite an effective field suture using twisted spider silk.\n\n{class}, bring me some from the spiders that stalk these highlands.", objectives = "Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands.", progress = "The results are in, I've got good news and bad news for you.\n\nOh, excuse me.", completion = "Splendid spider string. When you're being stitched back together, a little infection is the... least of your concerns.\n\nAhem, excuse me once again. Doctor humor.\n\nThanks for helping out the medical ward, {name}. If only we could get this kind of help more regularly." }
WordHunterWoW_QuestEN[97540] = { title = "Oasis", description = "Oh, this fresh water smells so good... \n\nI'm going to stop for a moment and have a quick swim and a drink.", objectives = "Show the newly quenched Tooga the way back to his wife, Torta." }
WordHunterWoW_QuestEN[97558] = { title = "Hides for the Forsaken", description = "One part of undeath no one mentions is what happens when we are injured. How does the skin of an undead heal itself?\n\nWell, it doesn't.\n\nOurs is a cursed life, {name}. We must take from the living to further our own existence.\n\nWhen we sustain an injury, we must replace our skin which usually means animal hides. Since different hide thicknesses are better for different places on our bodies a variety is key!\n\nBring me wing membranes of a duskbat, hides from a darkhound and skin of a Vile Fin murloc.", objectives = "Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin.", progress = "Have you gathered the skin I inquired about? Our stocks are running low.\n\nIt may seem odd to ask for murloc skin but it works well for internal membranes, or surfaces like cheeks or mouths.\n\nSimilarly, the duskbat wing membranes are especially suited for more delicate areas, like faces or fingers. It prevents the skin from being too... thick.", completion = "Ah, excellent! Thank you for acquiring these. I can promise they will be put to good use." }
WordHunterWoW_QuestEN[97583] = { title = "WRIGGLE.", description = "<The little slime seems delighted and is attempting to mirror your motions as you dance. It begins to look weary though.\n\nThe little slime hovers over a bit of sludge and absorbs it, looking slightly rejuvenated.\n\nIt seems all of this dancing has tuckered it out. Perhaps someone in the Undercity canals sells more of this nutritious sludge?>", objectives = "Purchase Nutritious Slime Sludge and return to your befriended excitable slime. If it seems tired, try dancing with it again to catch its attention.", progress = "<The slime seems to regard you with interest.>", completion = "<The slime shudders with newfound energy. It seems to want to follow you, now that it has associated you with food.>" }
WordHunterWoW_QuestEN[97617] = { title = "Safety Checks", description = "Hullo there, you look like the helpful sort.\n\nThe name's Dorgaron, and I'm with the Explorers' League. We've not had the best of luck with diggin' in the Badlands, but I know darn well there's artifacts to find and collect!\n\nBefore I can convince the boss to let us send another crew out here, I need to prove that the dig sites are safe AND haven't been picked clean.\n\nIf you find yourself down south, gather a few reasonably intact artifacts and some leftover equipment that hasn't been smashed yet.", objectives = "Recover 8 Unstudied Artifacts, an Explorers' League Mining Helmet, and a Pristine Mattock and bring them to Dorgaron at the border of Loch Modan and the Badlands." }
WordHunterWoW_QuestEN[97663] = { title = "Supplies and Studies", description = "I noticed a few rocks that seemed unusual in the Dustbowl. Upon closer inspection, I saw that they had carvings! I could not resist making rubbings of them to study later.\n\nThe nearby ogres took notice of my presence and before I could even react, I woke up under the care of the innkeeper, and with a terrible headache.\n\nNow, I am down all of my supplies and without any study material while I heal. Can you venture to the east in search of my pack, and take rubbings of the etchings yourself?", objectives = "Slay ogres in the Dustbowl for Mus'hale's Stolen Supplies and use them to collect rubbings of the nearby stone etchings, then return to Mus'hale at Kargath." }
WordHunterWoW_QuestEN[97821] = { title = "Mirage Mirror", description = "<Upon the elemental's demise, a relic fell from its core that glimmered in the sand.\n\nAs it was tilted in your hands, the reflection of the surrounding environment obscured it from your own view. Only once you saw a cracked surface that warped the reflection was it clearly visible again.\n\nPerhaps someone would be interested in this discovery.>", objectives = "Find someone in the Badlands that would be interested in this discovery." }
WordHunterWoW_QuestEN[97883] = { title = "End of the Dark Horde", description = "Bring Blackhand's head to Major Mattingly at the city gates. He and his men will proclaim the great victory you have achieved this day, so that the rest of the Alliance may be inspired by it.\n\nYou've done a great justice this day, {name}. One that all will remember--including our enemies.", objectives = "Bring the Head of Rend Blackhand to Major Mattingly in Stormwind." }
WordHunterWoW_QuestEN[97884] = { title = "Armory of Sunnyglade", description = "You look like a healthy, able-bodied {race}. I am looking for someone to travel to Sunnyglade, in the Riverglades just north of the Redridge Mountains.\n\nMy family owned an armory there, once. Now I imagine it is a burnt husk, but I would have you retrieve a tome containing my family's ancestral armor crafting techniques. It was originally in the basement, so hopefully it has not succumbed to the elements just yet.", objectives = "Travel to Sunnyglade in the Riverglades and recover the tome of Tremayne Family Blacksmithing Techniques." }
WordHunterWoW_QuestEN[97891] = { title = "Prompt Potion Runner", description = "You! Quickly, I need you to bring this potion across the slime canal to Doctor Martin Felben in the Apothecarium!\n\nIt has a very limited shelf life, and no I can't go myself, my knees rattle and pop out if I attempt to run.\n\nJust another lovely side effect of undeath, apparently.\n\nBut we're wasting time! Here, take this and go!\n\n<Alessandro makes a shooing motion.>", objectives = "Bring the Unstable Potion to Doctor Martin Felben in the Apothecarium within the time limit.", completion = "Ah, marvelous! I had been waiting for Alessandro's potion to arrive. The last six he sent destabilized along the way, but you've made it just in time!\n\nHere, take this for your effort. That is all for now, unless you have other business with me?\n\nIf not, remove yourself so I may continue my experiments unhindered." }
WordHunterWoW_QuestEN[97894] = { title = "Business in Auberdine", description = "Pleasure to make yer acquaintance! Name's Borgus, of the one and only Steelhand family. You can always count on a Steelhand fer a fair deal!\n\nA few weeks back me brother Gorbold joined up with a merchant stall in Auberdine. Plenty of coin to be made supplyin' ships there, let me tell you! Lucky sod.\n\nI haven't heard from him since--mind checking on him if yer heading that way?\n\nThere's a new ship in the harbor that will take ye straight there. Head to the southern-most dock; can't miss it!", objectives = "Check on Gorbold Steelhand in Auberdine in Darkshore.\n\nBorgus mentioned a boat on the southern-most dock in Stormwind Harbor that can take you there.", completion = "Old Borgy sent you? Always looking out for me.\n\nWe could certainly use another set of hands around here. Business has all but stopped with the recent tragedy, and I think you could help set things right." }
WordHunterWoW_QuestEN[97899] = { title = "Camping 101: Alchemy", description = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste.", objectives = "Speak with Whuut in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There ya have it, directions for your very own Mana Well. Most folks don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to try it out.\n\nNo camp is complete without a campfire. You'll need one of those as the basis of your camp. Most cooks can teach you to make a fire. Check in with someone who can train you in cooking if you haven't already learned the basics." }
WordHunterWoW_QuestEN[97900] = { title = "Camping 101: Blacksmithing", description = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons.", objectives = "Speak with Dwukk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Sharpening Wheel. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97901] = { title = "Camping 101: Enchanting", description = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.", objectives = "Speak with Jhag in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, you can craft your very own Enchanted Lute. Most folks don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to try it out.\n\nNo camp is complete without a campfire. You'll need one of those as the basis of your camp. Most cooks can teach you to make a fire. Check in with someone who can train you in cooking if you haven't already learned the basics." }
WordHunterWoW_QuestEN[97902] = { title = "Camping 101: Engineering", description = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells.", objectives = "Speak with Mukdrak in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Reagent Bot. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97903] = { title = "Camping 101: First Aid", description = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a {class}.\n\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives.", objectives = "Speak with Rawrk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "I can teach you once you've gained some skill with your profession.", completion = "There you have it, you can now craft your very own First Aid Kit. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97904] = { title = "Camping 101: Fishing", description = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\n\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that.", objectives = "Speak with Lau'Tiki near Sen'jin Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "I can teach you once you've gained some skill as a fisherman.", completion = "Dere ya have it, ya be craftin' your very own Fish Bowl. Most folk don't be carin' much for camps being set up in da center of town, so ya be needin' ta head into da wilderness if ya be wantin' to try it out.\n\nNo camp is complete without a campfire, mon. Ya be needin' one of dose before ya be startin' up your camp. Most cooks be teachin' ya ta make a fire. Check in with someone who can train ya in da culinary arts if ya haven't already learned da basics." }
WordHunterWoW_QuestEN[97905] = { title = "Camping 101: Herbalism", description = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\n\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate.", objectives = "Speak with Jandi in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "Dere ya have it, ya be craftin' your very own Incense Candle. Most folk don't be carin' much for camps being set up in da center of town, so ya be needin' ta head into da wilderness if ya be wantin' to try it out.\n\nNo camp is complete without a campfire, mon. Ya be needin' one of dose before ya be startin' up your camp. Most cooks be teachin' ya ta make a fire. Check in with someone who can train ya in da culinary arts if ya haven't already learned da basics." }
WordHunterWoW_QuestEN[97906] = { title = "Camping 101: Leatherworking", description = "You've become a leatherworker. Good for you, {class}. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\n\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels.", objectives = "Speak with Karolek in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, your very own camp tent. Most folk don't care much for tents being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97907] = { title = "Camping 101: Mining", description = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess.", objectives = "Speak with Krunn in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Lodestone. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97908] = { title = "Camping 101: Skinning", description = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.", objectives = "Speak with Thuwd in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Camp Chair. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97914] = { title = "Expanding Horizons", description = "Auberdine is a humble place, {class}. You won't hear its name spoken in the boughs of Darnassus. Most reference only what the Sundering took from us--the thriving cities of Ameth'Aran, Bashal'Aran, and... Lathar'Lazal.\n\nYet Auberdine remains in their shadow.\n\nI would see our work here recognized. A new vessel connects us to the kingdom of Stormwind, bringing life and supplies to our shores. I beseech you to join its next voyage, and bring this letter to a human called Baros Alexston.\n\nMake our home known.", objectives = "Bring Thundris' Letter to Baros Alexston in Stormwind.\n\nThundris mentioned a boat in Auberdine that can take you there.", progress = "I can smell the sea on you, friend!\n\n<Baros laughs.>\n\nWhat brings you to Stormwind?", completion = "<Baros opens the letter and begins to read it, his smile fading.>" }
WordHunterWoW_QuestEN[97915] = { title = "Camping 101: Alchemy", description = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste.", objectives = "Speak with Alchemist Mallory in Elwynn Forest near Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Mana Well. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97916] = { title = "Camping 101: Blacksmithing", description = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons.", objectives = "Speak with Smith Argus in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, you can now craft your very own Sharpening Wheel. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
